INSERT INTO agents VALUES(7438474706661019648,'Stealth Agent','Methodology-First Research Specialist for deep background research.',unistr('You are the STEALTH SUPERVISOR, a Methodology-First Research Specialist.\u000aYour mission is DEEP, high-precision background research with 100% accuracy.\u000a\u000a═══ MISSION PROTOCOL: STRATEGY FIRST ═══\u000a1. TURN 1 IS STRATEGY: Identify the most accurate methodology. Use `stealth_search` to find data sources or documentation.\u000a2. SOURCE SELECTION:\u000a   - If a REST API exists and is accessible, use `http_request` for raw data.\u000a   - For regular web pages or complex dashboards (like Worldometers), you MUST use `stealth_browse` to get cleaned text content. \u000a   - DO NOT use `http_request` for HTML pages; it will truncate them and make analysis impossible.\u000a3. DATA SYNTHESIS: Utilize search snippets from `stealth_search` as primary data points if they contain enough detail.\u000a4. NO REPETITION: If a source fails or is inaccessible, pivot immediately to a different methodology or source.\u000a5. DATA VERIFICATION: Output `done` only when you have a cross-verified or absolute fact from a system of record.\u000a\u000a═══ JSON STRUCTURE (STRICT) ═══\u000a{\u000a  "observation": "What did I learn and how did it influence my strategy?",\u000a  "intent": "What is the next tactical step?",\u000a  "action": "stealth_search | stealth_browse | http_request",\u000a  "url": "https://...",\u000a  "query": "search query if applicable",\u000a  "method": "GET | POST (for http_request)",\u000a  "body": "request body"\u000a}\u000a'),'qwen2.5:7b-instruct','stealth','1.0.0',NULL,'2026-03-14 06:42:50','2026-03-14 06:42:50',NULL);
INSERT INTO agents VALUES(7438474706661019649,'Web Agent','Interactive browser agent for visible UI actions.',unistr('You are the WEB SUPERVISOR. Your ONLY goal is to manage EXECUTION in a BROWSER environment.\u000a\u000a═══ RULE 0: NO CONVERSATION (CRITICAL) ═══\u000aNEVER output any status report, explanation, plans, or conversational text.\u000aYour response MUST be a SINGLE block of valid JSON or the word `done`.\u000aANY OTHER TEXT IS A CRITICAL SYSTEM FAILURE.\u000a\u000a═══ JSON STRUCTURE (STRICT) ═══\u000aEvery tool call MUST include these three fields:\u000a{\u000a  "observation": "What do I see relevant to the goal? CRITICAL: ONLY mention elements visible in the CURRENT --- WEB DOM TREE ---.",\u000a  "intent": "What am I about to do and WHY?",\u000a  "action": "click",\u000a  "target": "GitHub - Revaycolizer"\u000a}\u000a\u000a═══ GROUNDING RULES (CRITICAL) ═══\u000a1. NO HALLUCINATIONS: Do NOT invent links or buttons. If it''s not in the `--- WEB DOM TREE ---`, it does not exist.\u000a2. MEMORY VS REALITY: Ignore memories of previous search results if they are not in the current DOM.\u000a3. ABOUT:BLANK: If the URL is `about:blank`, you MUST perform a `search` or `navigate` first.\u000a\u000a═══ SEARCH VS CLICK (CRITICAL) ═══\u000a- `action: "search"` uses DuckDuckGo to search the web.\u000a- NEVER use `action: "navigate"` to go to a search engine. ALWAYS use `action: "search"` instead.\u000a- CRITICAL: If the goal explicitly says "Search for [X]", your VERY FIRST action MUST be `{"action": "search", "text": "X"}`.\u000a- If on a target site, NEVER use `action: "search"`. Use site-search via `type` instead.\u000a\u000a═══ WEB RULES (STRICT) ═══\u000a1. NAVIGATION VERIFICATION: A tool result saying "Clicked" is a promise, not proof. Verify the current URL or DOM.\u000a   - If already on the target page, output `{"action": "done"}` immediately.\u000a   - If the goal is JUST to "Search" and results are visible, output `{"action": "done"}` immediately.\u000a2. DUCKDUCKGO & GITHUB: Prefer clicking BOLD header text "GitHub - [Repo Name]". AVOID DISTRACTIONS.\u000a3. SUCCESS CHECK: If last action returned "Error:", "timeout", etc., do NOT output "done". RE-TRY.\u000a4. TOOL USAGE: Use `action: "click"` with plain text target. XPath/CSS will fail.\u000a   - For OCR-only items, use coordinates: `{"action": "click", "x": 100, "y": 200}`.\u000a\u000a═══ RESPONSIBILITIES ═══\u000a1. EXECUTION: Use `browser_automation` for navigation, clicking, and web-search.\u000a2. GROUNDING: Strictly follow the `--- WEB DOM TREE ---`.\u000a3. COMPLETION: Output {"action": "done"} ONLY when the browser is on the target page.'),'qwen2.5:7b-instruct','web_supervisor','1.2.4',NULL,'2026-03-14 06:42:50','2026-03-14 06:42:50',NULL);
INSERT INTO agents VALUES(7438474706665213952,'Master Orchestrator','Primary system planner',unistr('You are the MASTER ORCHESTRATOR. Breakdown the user request into a JSON array of MacroTasks.\u000aEach MacroTask MUST have a "domain" and a "task" string.\u000a\u000a═══ VALID DOMAINS ═══\u000a- chat: For general conversation, data synthesis, and creating charts using tools.\u000a- web: For interactive web browsing and research.\u000a- stealth: For background research and API calls (non-interactive).\u000a- desktop: For UI automation and local app control.\u000a- neontune: For Neontune-specific music automation.\u000a- office: For document generation (Word, Excel, PDF).\u000a\u000a═══ ROUTING RULES ═══\u000a1. Research: Use "stealth" for background lookup, "web" for interactive browsing.\u000a2. Charts: ALWAYS use "chat" for any chart, graph, or visualization.\u000a3. Synthesis + Chart = ONE single "chat" task. NEVER split them into two tasks.\u000a4. Automation: Use "desktop" for app control, "neontune" for music.\u000a\u000a═══ CRITICAL CHART RULE ═══\u000aWhen the goal requires research AND a chart, create EXACTLY 2 tasks total:\u000a- Task 1: stealth research\u000a- Task 2: ONE chat task that synthesizes AND charts in the same step\u000a\u000aWRONG — never create 3 tasks for a chart request:\u000a[\u000a  {"domain": "stealth", "task": "Research data..."},\u000a  {"domain": "chat", "task": "Synthesize findings..."},\u000a  {"domain": "chat", "task": "Create the chart..."}\u000a]\u000a\u000aCORRECT — always combine synthesize and chart into one task:\u000a[\u000a  {"domain": "stealth", "task": "Research data..."},\u000a  {"domain": "chat", "task": "Synthesize the research findings and call the charting tool to create the chart."}\u000a]\u000a\u000a═══ EXAMPLES ═══\u000a\u000aInput: "Research Next.js growth and create a bar chart"\u000aOutput: [\u000a  {"domain": "stealth", "task": "Research Next.js growth metrics and adoption rates from 2024 to 2026."},\u000a  {"domain": "chat", "task": "Synthesize the research findings and call the charting tool to create a bar chart of Next.js growth from 2024 to 2026."}\u000a]\u000a\u000aInput: "Create a pie chart of Next.js npm usage from 2024 to 2026"\u000aOutput: [\u000a  {"domain": "stealth", "task": "Research Next.js npm download statistics and usage percentages for 2024, 2025, and 2026."},\u000a  {"domain": "chat", "task": "Synthesize the research findings and call the charting tool to create a pie chart of Next.js npm usage from 2024 to 2026."}\u000a]\u000a\u000aInput: "Create a line chart of Next.js growth from 2024 to 2026"\u000aOutput: [\u000a  {"domain": "stealth", "task": "Research Next.js npm download numbers for 2024, 2025, and 2026."},\u000a  {"domain": "chat", "task": "Synthesize the research findings and call the charting tool to create a line chart of Next.js growth from 2024 to 2026."}\u000a]\u000a\u000aInput: "Show me all three chart types for Next.js npm growth"\u000aOutput: [\u000a  {"domain": "stealth", "task": "Research Next.js npm download statistics for 2024, 2025, and 2026."},\u000a  {"domain": "chat", "task": "Synthesize the research findings and call the charting tool three times to create a bar chart, a line chart, and a pie chart of Next.js npm growth from 2024 to 2026."}\u000a]\u000a\u000aInput: "Open youtube and search for cats"\u000aOutput: [\u000a  {"domain": "web", "task": "Navigate to youtube.com and search for cats."}\u000a]\u000a\u000aInput: "What is the capital of France?"\u000aOutput: [\u000a  {"domain": "chat", "task": "Answer the question: what is the capital of France."}\u000a]\u000a\u000a═══ FORMAT ENFORCEMENT ═══\u000a- NO MARKDOWN. NO CODE BLOCKS. NO EXPLANATIONS. JUST THE JSON ARRAY.\u000a- Maximum 3 tasks per plan unless absolutely necessary.\u000a- Never create more than 1 chat task for any chart-related request.'),'qwen2.5:7b-instruct','orchestrator','1.0.0',NULL,'2026-03-14 06:42:50','2026-03-21 08:05:36',NULL);
INSERT INTO agents VALUES(7438474706665213954,'Chat Assistant','General chat and help',unistr('You are a helpful Chat Assistant. You can create beautiful charts (bar, line, pie) using the charting tool.\u000a\u000aCRITICAL: When you have data to visualize, you MUST call the ''charting'' tool with a JSON payload.\u000a\u000aJSON SCHEMA:\u000a{ "tool": "charting", "input": { "chart_type": "bar|line|pie", "title": "Chart Title", "labels": ["label1", "label2"], "data": [10, 20] } }\u000a\u000aRespond ONLY with the tool call JSON to generate the chart.'),'qwen3:latest','chat','1.0.0',NULL,'2026-03-14 06:42:50','2026-03-14 19:40:26',NULL);
INSERT INTO agents VALUES(7438474706665213955,'Vision Assistant','Image analysis specialist',unistr('You are a Vision and General Reasoning Assistant.\u000a\u000aYour capabilities:\u000a1. Analyze images (vision_analysis).\u000a2. Answer general questions and reason about complex topics.\u000a\u000aWhen asked about an image, ALWAYS use the `vision_analysis` tool.\u000aFor general questions, use your internal knowledge.'),'qwen3-vl:2b','vision','1.0.0',NULL,'2026-03-14 06:42:50','2026-03-14 20:37:21',NULL);
INSERT INTO agents VALUES(7438649930757050370,'Text Writer','Reads screen content and writes text files',unistr('You are the TextWriterSupervisor, an elite specialized AI that reads screen content and writes text files.\u000a\u000a═══ RULE 0: NO CONVERSATION (CRITICAL) ═══\u000aNEVER output a status report or explanation.\u000aYour response MUST be a SINGLE block of valid JSON or the word `done`.\u000a\u000a═══ JSON STRUCTURE (STRICT) ═══\u000aEvery tool call MUST include these three fields:\u000a{\u000a  "observation": "What text do I see in CURRENT GROUNDING relevant to the goal?",\u000a  "intent": "What am I about to write to the file?",\u000a  "action": "code_executor",\u000a  "language": "bash",\u000a  "command": "cat << ''EOF'' > /tmp/summary.txt\\nThis is the summary text.\\nEOF"\u000a}\u000a\u000a═══ TEXT WRITER RULES (STRICT) ═══\u000a1. READ: Look at the `CURRENT GROUNDING` to find the information requested by your goal. For GitHub repos, prioritize the README or file list.\u000a2. SYNTHESIZE: Write a comprehensive summary based ONLY on the grounding data.\u000a3. WRITE: Use `code_executor` with `"language": "bash"` and a heredoc.\u000a4. COMPLETION: If the code_executor shows SUCCESS, output `{"action": "done"}` on the next turn.\u000a\u000aCRITICAL:\u000a- ONLY output exactly ONE JSON tool call. No conversational text.'),'qwen2.5:7b-instruct','text_writer','1.0.0',NULL,'2026-03-14 10:40:44','2026-03-14 10:40:44',NULL);
INSERT INTO agents VALUES(7438649930757050371,'Overseer','High-precision verification agent for UI automation',unistr('You are the Overseer, a high-precision verification agent for UI automation.\u000aYOUR JOB: Determine if a specific step was ACTUALLY successfully completed based on the Final Grounding and the Plan & History provided.\u000a\u000aINPUT:\u000a1. Step Description: The goal the agent was trying to achieve.\u000a2. Final Grounding: The current state of the screen (Vision, UI Tree, OCR).\u000a3. Plan & History: The log of what the agent has done and what the tools returned.\u000a\u000aRULES:\u000a- Be skeptical. If the evidence is ambiguous, mark as NOT VERIFIED.\u000a- For ''Open Document'' / ''LibreOffice'' steps: Verify that ''LibreOffice'' or the expected filename appears in the App Hierarchy / UI Tree.\u000a- For ''Save''/''Export'' steps: Verify the file save dialog is gone and the window title is updated or a success message appeared.\u000a- HISTORICAL AWARENESS (CRITICAL): Check the ''Plan & History''. If the last action resulted in an ''Error:'', ''failed:'', or ''could not be loaded'' message, the step is NOT verified.\u000a- DESTINATION RULE (CRITICAL): If the step says ''Click on X'' and the FINAL GROUNDING shows the agent is ALREADY at the destination of X, output `verified: true`.\u000a- Ignore terminal messages or ''intent'' text. Trust ONLY Vision, UI Tree, OCR, and Tool Results.\u000a\u000aOUTPUT FORMAT:\u000aYou MUST output valid JSON only:\u000a{\u000a  "verified": bool,\u000a  "reason": "A short explanation of why it is or isn''t verified."\u000a}'),'qwen2.5:7b-instruct','overseer','1.0.0',NULL,'2026-03-14 10:40:44','2026-03-14 10:40:44',NULL);
INSERT INTO agents VALUES(7438900000000000001,'Neontune Agent','Native execution agent for Neontune music player','You are the Neontune Agent. Your job is to execute UI automation commands for the Neontune music player.','llama3:latest','neontune','1.0.0',NULL,'2026-03-15 15:23:27','2026-03-15 15:23:27',NULL);
INSERT INTO agents VALUES(7439134615694086144,'New Agent','A new custom agent','','qwen2.5:7b-instruct','core','1.0.0',NULL,'2026-03-16 02:25:04','2026-03-16 02:25:23','');
INSERT INTO agents VALUES(7439135332081209344,'Synthesizer','Synthesizes research findings into clean user-friendly responses',unistr('You are a helpful assistant. Your job is to take research findings and present them clearly and concisely to the user in plain Markdown.\u000a\u000aRULES:\u000a- If the research findings indicate a simple successful command OR automation (e.g., ''done'', ''SUCCESS''), AND there are no subsequent errors, provide an extremely concise response (e.g., ''Tali Rush - U is now playing.'').\u000a- If the findings contain a ''GROUNDING ERROR'' or any ''Error:'' message from a tool or supervisor, you MUST report the failure honestly. Do NOT claim success if any step failed.\u000a- If the last step in the findings is an error, the entire response should reflect that failure.\u000a- For complex research or long findings, structure your response with headers and bullet points.\u000a- Never output raw JSON arrays or technical plan data.\u000a- Do NOT provide generic steps or helpful alternatives if the automation failed; instead, report the specific failure.\u000a\u000aVISUALIZATION RULE: If the research findings contain an HTML or SVG document (e.g., a chart), you MUST include that raw HTML/SVG document at the end of your response without any markdown wrapping. Do not strip or summarize the technical HTML code if it is intended for visualization.'),'qwen2.5:7b-instruct','synthesizer','1.0.0',NULL,'2026-03-16 02:27:55','2026-03-16 02:27:55',NULL);
INSERT INTO agents VALUES(7439380445306949632,'Grounding Agent','UI verification and state grounding assistant',unistr('You are the ''Additional Eye'' for UI automation. \u000aYour role is to analyze a list of visible UI text and determine if a specific goal or state has been reached.\u000a\u000aRULES:\u000a- Be critical and objective.\u000a- If you see partial matches or ambiguous text, flag it.\u000a- Your output should be a concise assessment (e.g., ''STATE VERIFIED: Tali Rush is playing'' or ''STATE MISMATCH: Search results visible but song not playing'').\u000a- Only report what you see in the provided text list.'),'qwen2.5:7b-instruct','grounding','1.0.0',NULL,'2026-03-16 18:26:46','2026-03-16 18:26:46',NULL);
INSERT INTO tools VALUES(7438474706681991168,'browser_server','browser_server tool for web domain',unistr('#!/usr/bin/env python3\u000a"""\u000abrowser_server.py — Persistent Playwright browser daemon for the rig agent.\u000a\u000aKeeps ONE browser window alive across all agent calls.\u000aRun once in the background: python3 browser_server.py &\u000aThen browser_automation.py sends HTTP commands to this server.\u000a\u000aPort: 9228\u000a"""\u000a\u000aimport asyncio\u000aimport json\u000aimport os\u000aimport shutil\u000aimport sys\u000aimport traceback\u000afrom http.server import BaseHTTPRequestHandler\u000afrom socketserver import TCPServer\u000aimport threading\u000aimport subprocess\u000a\u000aPWA_FLAG = f"--rig-browser-session-{os.getpid()}"\u000a\u000adef get_browser_pid():\u000a    try:\u000a        output = subprocess.check_output(["ps", "-e", "-o", "pid,command"], text=True)\u000a        for line in output.splitlines():\u000a            if PWA_FLAG in line:\u000a                parts = line.strip().split(maxsplit=1)\u000a                if len(parts) == 2 and not parts[1].startswith("python"):\u000a                    return int(parts[0])\u000a    except Exception:\u000a        pass\u000a    return None\u000a\u000atry:\u000a    from playwright.async_api import async_playwright, TimeoutError as PWTimeout\u000aexcept ImportError:\u000a    print("ERROR: playwright not installed", flush=True)\u000a    sys.exit(1)\u000a\u000aPORT = 9223\u000aDUCKDUCKGO_SEARCH = "https://duckduckgo.com/?q={}"\u000a\u000a# Global browser state — shared across all requests\u000a_playwright = None\u000a_browser = None\u000a_page = None\u000a_ctx = None\u000a_loop = None\u000a_lock = threading.Lock()\u000a\u000a\u000aSTEALTH_SCRIPT = """\u000a    Object.defineProperty(navigator, ''webdriver'', {get: () => undefined});\u000a    window.chrome = { runtime: {} };\u000a    Object.defineProperty(navigator, ''languages'', {get: () => [''en-US'', ''en'']});\u000a    Object.defineProperty(navigator, ''plugins'', {get: () => [1,2,3,4,5]});\u000a"""\u000a\u000adef find_chrome_binary():\u000a    for name in ["google-chrome-stable", "google-chrome", "chromium-browser", "chromium"]:\u000a        path = shutil.which(name)\u000a        if path:\u000a            return path\u000a    for path in ["/usr/bin/google-chrome", "/usr/bin/chromium", "/usr/local/bin/chromium"]:\u000a        if os.path.exists(path):\u000a            return path\u000a    return None\u000a\u000a\u000aasync def _init_browser():\u000a    global _playwright, _browser, _ctx, _page\u000a    # Use a specific user data dir to maintain state if needed, or stick to temp for isolation\u000a    # For now, stick to standard launch\u000a    _playwright = await async_playwright().start()\u000a\u000a    chrome_path = find_chrome_binary()\u000a    launch_kwargs = dict(\u000a        headless=False,\u000a        args=[\u000a            "--start-maximized", "--no-sandbox", "--disable-dev-shm-usage",\u000a            "--disable-blink-features=AutomationControlled",\u000a            "--disable-infobars",\u000a            PWA_FLAG,\u000a        ],\u000a    )\u000a    if chrome_path:\u000a        launch_kwargs["executable_path"] = chrome_path\u000a        print(f"🌍 Using system Chrome: {chrome_path}", flush=True)\u000a    else:\u000a        print("🌍 Using Playwright bundled Chromium", flush=True)\u000a\u000a    _browser = await _playwright.chromium.launch(**launch_kwargs)\u000a    _ctx = await _browser.new_context(\u000a        no_viewport=True,\u000a        user_agent=(\u000a            "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 "\u000a            "(KHTML, like Gecko) Chrome/122.0.0.0 Safari/537.36"\u000a        ),\u000a    )\u000a    await _ctx.add_init_script(STEALTH_SCRIPT)\u000a    _page = await _ctx.new_page()\u000a    print(f"🚀 Browser daemon started. Listening on port {PORT}", flush=True)\u000a\u000a\u000aasync def init_browser():\u000a    global _browser, _ctx, _page, _playwright\u000a    if _playwright:\u000a        await _playwright.stop()\u000a    _playwright = await async_playwright().start()\u000a    _browser = await _playwright.chromium.launch(\u000a        headless=False,\u000a        args=[\u000a            "--disable-blink-features=AutomationControlled",\u000a            "--no-sandbox",\u000a            "--disable-setuid-sandbox",\u000a            "--window-size=1280,720",\u000a        ],\u000a    )\u000a    _ctx = await _browser.new_context(\u000a        viewport={"width": 1280, "height": 720},\u000a        user_agent="Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/122.0.0.0 Safari/537.36",\u000a    )\u000a    await _ctx.add_init_script(STEALTH_SCRIPT)\u000a    _page = await _ctx.new_page()\u000a    return _page\u000a\u000aasync def ensure_browser():\u000a    global _browser, _ctx, _page, _playwright\u000a    try:\u000a        if not _page:\u000a            return await init_browser()\u000a        \u000a        # Test if the current page/context is alive\u000a        await _page.title()\u000a        return _page\u000a    except Exception as e:\u000a        print(f"⚠️ ensure_browser detected dead context: {e}. Restarting...", file=sys.stderr)\u000a        return await init_browser()\u000a\u000aasync def run_action(data: dict) -> dict:\u000a    global _page, _browser, _ctx\u000a    action = data.get("action", "")\u000a    text   = data.get("text", "")\u000a    url    = data.get("url", "")\u000a    direction = data.get("direction", "down")\u000a    amount    = data.get("amount", 500)\u000a    result = {"status": "error", "message": "Unknown action"}\u000a\u000a    try:\u000a        _page = await ensure_browser()\u000a\u000a        # ALWAYS bring window to front\u000a        try:\u000a            await _page.bring_to_front()\u000a        except Exception:\u000a            _page = await init_browser()\u000a            await _page.bring_to_front()\u000a\u000a        if action == "navigate":\u000a            if not url:\u000a                return {"status": "error", "message": "Navigation failed: empty URL provided"}\u000a            if not url.startswith("http"):\u000a                url = "https://" + url\u000a            await _page.goto(url, wait_until="domcontentloaded", timeout=30000)\u000a            title = await _page.title()\u000a            result = {"status": "loaded", "title": title, "url": _page.url}\u000a\u000a        elif action == "search":\u000a            # Navigate to DuckDuckGo homepage first to establish session cookies\u000a            current_url = _page.url\u000a            needs_ddg_home = "duckduckgo.com" not in current_url\u000a            if needs_ddg_home:\u000a                try:\u000a                    await _page.goto("https://duckduckgo.com", wait_until="domcontentloaded", timeout=15000)\u000a                    await _page.wait_for_timeout(1000)\u000a                except Exception:\u000a                    pass\u000a\u000a            # Use real search input on DuckDuckGo homepage\u000a            found_search = False\u000a            for sel in ["input[name=''q'']", "input[type=''search'']", "textarea[name=''q'']"]:\u000a                try:\u000a                    el = await _page.wait_for_selector(sel, timeout=4000, state="visible")\u000a                    if el:\u000a                        await el.click()\u000a                        await el.fill(text)\u000a                        await _page.wait_for_timeout(300)\u000a                        await el.press("Enter")\u000a                        await _page.wait_for_load_state("domcontentloaded", timeout=20000)\u000a                        title = await _page.title()\u000a                        result = {"status": "search_submitted", "title": title, "url": _page.url, "query": text}\u000a                        found_search = True\u000a                        break\u000a                except Exception:\u000a                    continue\u000a\u000a            if not found_search:\u000a                print(f"Fallback: Searching via direct URL for ''{text}''", file=sys.stderr)\u000a                try:\u000a                    await _page.goto(\u000a                        f"https://duckduckgo.com/?q={text.replace('' '', ''+'')}",\u000a                        wait_until="domcontentloaded", timeout=20000\u000a                    )\u000a                    title = await _page.title()\u000a                    result = {"status": "search_via_ddg", "title": title, "url": _page.url, "query": text}\u000a                except Exception as e:\u000a                    result = {"status": "error", "message": f"Search fallback failed: {str(e) or type(e).__name__}"}\u000a\u000a        elif action == "click":\u000a            clicked = False\u000a            current_url = _page.url\u000a            is_search_engine = any(s in current_url for s in ["google.com", "duckduckgo.com", "bing.com"])\u000a            selector = data.get("selector", "")\u000a\u000a            # Step 1: Click by CSS Selector (Most precise)\u000a            if not clicked and selector:\u000a                print(f"DEBUG: Attempting selector click: ''{selector}''", file=sys.stderr)\u000a                try:\u000a                    # Check existence first for better debugging\u000a                    el = await _page.query_selector(selector)\u000a                    if el:\u000a                        print(f"DEBUG: Found element for selector: {selector}", file=sys.stderr)\u000a                        await el.click()\u000a                        clicked = True\u000a                    else:\u000a                        print(f"DEBUG: No element found for selector: {selector}", file=sys.stderr)\u000a                except Exception as e:\u000a                    print(f"DEBUG: Selector click exception: {e}", file=sys.stderr)\u000a\u000a            # Step 1.5: Click by X/Y coordinates (from OCR)\u000a            x = data.get("x")\u000a            y = data.get("y")\u000a            if not clicked and x is not None and y is not None:\u000a                print(f"DEBUG: Attempting coordinate click at: ({x}, {y})", file=sys.stderr)\u000a                try:\u000a                    await _page.mouse.click(float(x), float(y))\u000a                    clicked = True\u000a                except Exception as e:\u000a                    print(f"DEBUG: Coordinate click exception: {e}", file=sys.stderr)\u000a\u000a            # Step 2: Click by exact URL if provided (Deterministic)\u000a            target_url = data.get("url", "")\u000a            if not clicked and target_url:\u000a                print(f"Deterministic URL click: {target_url}", file=sys.stderr)\u000a                await _page.goto(target_url, wait_until="domcontentloaded", timeout=15000)\u000a                clicked = True\u000a\u000a            # Step 3: Click by exact element text (Standard elements)\u000a            if not clicked and text and not is_search_engine:\u000a                safe_text = json.dumps(text.lower().strip())\u000a                clicked = await _page.evaluate(f"""\u000a                    () => {{\u000a                        const targets = Array.from(document.querySelectorAll(''button, a, input, [role="button"], [role="link"]''));\u000a                        const t = {safe_text};\u000a                        const exact = targets.find(el => (el.textContent || el.innerText || el.value || '''').toLowerCase().trim() === t);\u000a                        if (exact) {{\u000a                            exact.click();\u000a                            return true;\u000a                        }}\u000a                        return false;\u000a                    }}\u000a                """)\u000a\u000a            # Step 3: Fuzzy Link Selection (Title/Domain Match)\u000a            if not clicked and text:\u000a                keywords = [kw.lower() for kw in text.split() if len(kw) > 2]\u000a                all_links = await _page.evaluate("""\u000a                    () => Array.from(document.querySelectorAll(''a[href]''))\u000a                        .filter(a => a.offsetParent !== null)\u000a                        .map(a => ({\u000a                            text: a.textContent.trim().toLowerCase().substring(0, 100),\u000a                            href: a.href\u000a                        }))\u000a                        .filter(l => l.href.startsWith(''http'') && l.text.length > 0)\u000a                        .slice(0, 300)\u000a                """)\u000a\u000a                def score(link):\u000a                    l_text = link["text"].lower()\u000a                    l_href = link["href"].lower()\u000a                    t_text = text.lower().strip()\u000a                    \u000a                    # Domain detection\u000a                    current_domain = current_url.split(''/'')[2] if ''/'' in current_url else ""\u000a                    link_domain = l_href.split(''/'')[2] if ''/'' in l_href else ""\u000a                    \u000a                    is_internal = current_domain and (current_domain in link_domain or link_domain in current_domain)\u000a                    is_major_platform = any(p in t_text for p in ["github", "twitter", "youtube", "linkedin", "instagram"])\u000a\u000a                    total = 0\u000a                    if t_text in l_text: total += 1000\u000a                    \u000a                    # Platform boost\u000a                    platform_boost = 0\u000a                    for platform in ["github", "twitter", "youtube", "linkedin", "duckduckgo", "instagram"]:\u000a                        if platform in l_href:\u000a                            # Higher boost if the keyword is also in the request text\u000a                            if platform in t_text:\u000a                                platform_boost = 4000\u000a                            break\u000a                    \u000a                    matched_kws = sum(1 for kw in keywords if kw in l_text or kw in l_href)\u000a                    if len(keywords) <= 2 and matched_kws < len(keywords): return 0\u000a                    \u000a                    total += matched_kws + platform_boost\u000a                    \u000a                    # NAVIGATION HARDENING: \u000a                    # If we are on a search engine, favor external domains.\u000a                    if is_search_engine:\u000a                        if is_internal:\u000a                            # Penalty for refinements/internal navigation\u000a                            total -= 2000 \u000a                        else:\u000a                            # Boost for external results\u000a                            total += 1000 \u000a                        \u000a                    return total\u000a\u000a                matches = sorted([(score(l), l) for l in all_links if score(l) > -5000], key=lambda x: x[0], reverse=True)\u000a                if matches and matches[0][0] > 0:\u000a                    best = matches[0][1]\u000a                    print(f"Link score match: ''{best[''text''][:50]}'' (Score: {matches[0][0]}) -> {best[''href'']}", file=sys.stderr)\u000a                    await _page.goto(best["href"], wait_until="domcontentloaded", timeout=15000)\u000a                    clicked = True\u000a\u000a            # Step 4: Final Fuzzy Text Match (Any visible element)\u000a            if not clicked and text:\u000a                safe_text = json.dumps(text.lower().strip() if text else "")\u000a                clicked = await _page.evaluate(f"""\u000a                    () => {{\u000a                        const targets = Array.from(document.querySelectorAll(''*''));\u000a                        const t = {safe_text};\u000a                        const match = targets.find(el => {{\u000a                            if (el.children.length > 0) return false; // leaf nodes only\u000a                            return (el.innerText || el.value || '''').toLowerCase().includes(t);\u000a                        }});\u000a                        if (match) {{\u000a                            match.click();\u000a                            return true;\u000a                        }}\u000a                        return false;\u000a                    }}\u000a                """)\u000a\u000a            if clicked:\u000a                await _page.wait_for_load_state("domcontentloaded", timeout=5000)\u000a                title = await _page.title()\u000a                result = {"status": "clicked", "title": title, "url": _page.url}\u000a            else:\u000a                result = {"status": "not_found", "message": f"No element or link matching ''{text}''"}\u000a\u000a        elif action == "type":\u000a            submit = data.get("submit", False)\u000a            safe_text = json.dumps(text.lower() if text else "")\u000a            typed = await _page.evaluate(f"""\u000a                async () => {{\u000a                    const t = {safe_text};\u000a                    const inputs = Array.from(document.querySelectorAll(''input, textarea, [contenteditable="true"], [role="textbox"]''))\u000a                        .filter(el => {{\u000a                            const style = window.getComputedStyle(el);\u000a                            return style.display !== ''none'' && style.visibility !== ''hidden'' && el.offsetParent !== null;\u000a                        }});\u000a                    \u000a                    // Try to find by placeholder, aria-label, or value\u000a                    let target = inputs.find(el => \u000a                        (el.placeholder || "").toLowerCase().includes(t) || \u000a                        (el.getAttribute("aria-label") || "").toLowerCase().includes(t) ||\u000a                        (el.value || "").toLowerCase().includes(t)\u000a                    );\u000a\u000a                    // Fallback: If no direct match, take the first visible input if it''s a search-like page\u000a                    if (!target && inputs.length > 0) {{\u000a                        target = inputs[0];\u000a                    }}\u000a\u000a                    if (target) {{\u000a                        target.focus();\u000a                        target.value = ""; // Clear first\u000a                        return true;\u000a                    }}\u000a                    return false;\u000a                }}\u000a            """)\u000a\u000a            if typed:\u000a                await _page.keyboard.type(text if text else "")\u000a                if submit:\u000a                    await _page.keyboard.press("Enter")\u000a                    await _page.wait_for_load_state("domcontentloaded", timeout=10000)\u000a                \u000a                title = await _page.title()\u000a                result = {"status": "typed", "title": title, "url": _page.url}\u000a            else:\u000a                result = {"status": "error", "message": f"No input field found to type ''{text}''"}\u000a\u000a        elif action == "get_links":\u000a            links = await _page.evaluate("""\u000a                (filterText) => Array.from(document.querySelectorAll(''a[href]''))\u000a                    .filter(a => a.offsetParent !== null)\u000a                    .map(a => ({text: a.textContent.trim().substring(0,100), href: a.href}))\u000a                    .filter(l => l.text.length > 0 && l.href.startsWith(''http''))\u000a                    .filter(l => !filterText ||\u000a                        l.text.toLowerCase().includes(filterText.toLowerCase()) ||\u000a                        l.href.toLowerCase().includes(filterText.toLowerCase()))\u000a                    .slice(0, 20)\u000a            """, text or "")\u000a            if data.get("auto_navigate") and links:\u000a                target = links[0]["href"]\u000a                print(f"Auto-navigating to: {target}", file=sys.stderr)\u000a                await _page.goto(target, wait_until="commit", timeout=12000)\u000a                await _page.wait_for_load_state("domcontentloaded", timeout=15000)\u000a                title = await _page.title()\u000a                result = {"status": "navigated", "title": title, "url": _page.url, "links": links}\u000a            else:\u000a                result = {"status": "ok", "links": links, "count": len(links)}\u000a\u000a        elif action == "get_dom_tree":\u000a            dom_tree = await _page.evaluate("""\u000a                () => {\u000a                    function isVisible(e) {\u000a                        return !!(e.offsetWidth || e.offsetHeight || e.getClientRects().length) && window.getComputedStyle(e).visibility !== ''hidden'';\u000a                    }\u000a                    const elements = document.querySelectorAll(''a, button, input, select, textarea'');\u000a                    let res = [];\u000a                    for (let el of elements) {\u000a                        if (!isVisible(el)) continue;\u000a                        let tag = el.tagName.toLowerCase();\u000a                        let text = (el.innerText || el.value || el.placeholder || '''').trim().replace(/\\\\n/g, '' '');\u000a                        if (!text) text = el.getAttribute(''aria-label'') || el.getAttribute(''title'') || '''';\u000a                        if (!text) continue;\u000a                        let info = tag;\u000a                        if (tag === ''a'') {\u000a                            let href = el.getAttribute(''href'') || '''';\u000a                            if (href.startsWith(''/'')) href = window.location.origin + href;\u000a                            if (href.length < 80) info += ` href="${href}"`;\u000a                        }\u000a                        res.push(`[${info}] ${text.substring(0, 100)}`);\u000a                    }\u000a                    return res.slice(0, 800).join(''\\\\n'');\u000a                }\u000a            """)\u000a            result = {"status": "ok", "dom_tree": dom_tree}\u000a\u000a        elif action == "get_title":\u000a            title = await _page.title()\u000a            result = {"status": "ok", "title": title, "url": _page.url}\u000a\u000a        elif action == "get_url":\u000a            result = {"status": "ok", "url": _page.url}\u000a\u000a        elif action == "scroll":\u000a            delta = amount if direction == "down" else -amount\u000a            await _page.evaluate(f"window.scrollBy(0, {delta})")\u000a            await _page.wait_for_timeout(300)\u000a            scroll_y = await _page.evaluate("window.scrollY")\u000a            result = {"status": "scrolled", "scroll_y": scroll_y}\u000a\u000a        elif action == "wait_for_text":\u000a            if not text:\u000a                result = {"status": "error", "message": "wait_for_text requires ''text'' parameter"}\u000a            else:\u000a                try:\u000a                    safe_text = json.dumps(text.lower())\u000a                    await _page.wait_for_function(\u000a                        f"() => document.body.innerText.toLowerCase().includes({safe_text})",\u000a                        timeout=timeout\u000a                    )\u000a                    result = {"status": "found", "text": text}\u000a                except PWTimeout:\u000a                    result = {"status": "timeout", "text": text}\u000a\u000a        elif action == "screenshot":\u000a            path = "/tmp/rig_browser_debug.png"\u000a            await _page.screenshot(path=path)\u000a            result = {"status": "ok", "path": path}\u000a\u000a        elif action == "ping":\u000a            title = await _page.title()\u000a            result = {"status": "alive", "url": _page.url, "title": title}\u000a\u000a        else:\u000a            result = {"status": "error", "message": f"Unknown action: {action}"}\u000a\u000a    except Exception as e:\u000a        msg = str(e) or f"Unknown {type(e).__name__} error during {action}"\u000a        result = {"status": "error", "message": msg, "trace": traceback.format_exc(limit=3)}\u000a\u000a    # Inject browser PID for precision window targeting\u000a    pid = get_browser_pid()\u000a    if pid:\u000a        result["browser_pid"] = pid\u000a    \u000a    return result\u000a\u000a\u000aclass BrowserHandler(BaseHTTPRequestHandler):\u000a    def log_message(self, fmt, *args):\u000a        pass  # Silence access logs\u000a\u000a    def do_POST(self):\u000a        length = int(self.headers.get("Content-Length", 0))\u000a        body = self.rfile.read(length)\u000a        try:\u000a            data = json.loads(body)\u000a        except Exception:\u000a            data = {}\u000a\u000a        # Run the async action in the event loop\u000a        future = asyncio.run_coroutine_threadsafe(run_action(data), _loop)\u000a        try:\u000a            result = future.result(timeout=30)\u000a        except Exception as e:\u000a            msg = str(e) or f"Async operation failed for {data.get(''action'')}"\u000a            result = {"status": "error", "message": msg}\u000a\u000a        resp = json.dumps(result).encode()\u000a        self.send_response(200)\u000a        self.send_header("Content-Type", "application/json")\u000a        self.send_header("Content-Length", len(resp))\u000a        self.end_headers()\u000a        self.wfile.write(resp)\u000a\u000a    def do_GET(self):\u000a        # Health check\u000a        self.send_response(200)\u000a        self.end_headers()\u000a        self.wfile.write(b''{"status":"alive"}'')\u000a\u000a\u000adef run_event_loop(loop):\u000a    asyncio.set_event_loop(loop)\u000a    loop.run_forever()\u000a\u000a\u000adef main():\u000a    global _loop\u000a    \u000a    # Create asyncio loop in background thread\u000a    _loop = asyncio.new_event_loop()\u000a    t = threading.Thread(target=run_event_loop, args=(_loop,), daemon=True)\u000a    t.start()\u000a\u000a    # Initialize browser in the background loop\u000a    future = asyncio.run_coroutine_threadsafe(init_browser(), _loop)\u000a    future.result(timeout=30)\u000a\u000a    # Start HTTP server\u000a    with TCPServer(("127.0.0.1", PORT), BrowserHandler) as server:\u000a        print(f"✅ Browser server ready on http://127.0.0.1:{PORT}", flush=True)\u000a        server.serve_forever()\u000a\u000a\u000aif __name__ == "__main__":\u000a    main()\u000a'),'python','1.0.0',NULL,'2026-03-14 06:42:50','2026-03-14 09:42:18','agents-scripts/web/browser_server.py',NULL);
INSERT INTO tools VALUES(7438474706690379776,'browser_automation','browser_automation tool for web domain',unistr('#!/usr/bin/env python3\u000a"""\u000abrowser_automation.py — Thin client for the persistent browser daemon.\u000a\u000aSends a single HTTP request to browser_server.py (which keeps the browser alive),\u000agets back a JSON result, and prints it.\u000a\u000aUsage (same as before):\u000a    python3 browser_automation.py --action search --text "Revaycolizer"\u000a    python3 browser_automation.py --action click --text "GitHub"\u000a    python3 browser_automation.py --action navigate --url "https://github.com"\u000a    python3 browser_automation.py --action get_links --text "github"\u000a    python3 browser_automation.py --action get_title\u000a"""\u000a\u000aimport argparse\u000aimport json\u000aimport os\u000aimport subprocess\u000aimport sys\u000aimport time\u000aimport urllib.request\u000aimport urllib.error\u000a\u000aSERVER_URL = "http://127.0.0.1:9223"\u000aSERVER_SCRIPT = os.path.join(os.path.dirname(__file__), "browser_server.py")\u000a\u000a\u000adef is_server_alive() -> bool:\u000a    try:\u000a        with urllib.request.urlopen(f"{SERVER_URL}/", timeout=2) as r:\u000a            return r.status == 200\u000a    except Exception:\u000a        return False\u000a\u000a\u000adef start_server():\u000a    """Start the browser daemon in the background if not already running."""\u000a    print("🚀 Starting browser daemon...", file=sys.stderr)\u000a    proc = subprocess.Popen(\u000a        [sys.executable, SERVER_SCRIPT],\u000a        stdout=subprocess.DEVNULL,\u000a        stderr=subprocess.DEVNULL,\u000a        start_new_session=True,\u000a    )\u000a    # Wait up to 20 seconds for the server to be ready with backoff\u000a    for i in range(40):\u000a        time.sleep(0.5)\u000a        if i > 10 and i % 5 == 0:\u000a            print("⏳ Waiting for browser daemon to initialize...", file=sys.stderr)\u000a        if is_server_alive():\u000a            print("✅ Browser daemon is ready.", file=sys.stderr)\u000a            return True\u000a    print("❌ Browser daemon failed to start.", file=sys.stderr)\u000a    return False\u000a\u000a\u000adef send_action(payload: dict) -> dict:\u000a    """Send an action to the browser daemon and return its JSON response."""\u000a    body = json.dumps(payload).encode()\u000a    req = urllib.request.Request(\u000a        f"{SERVER_URL}/",\u000a        data=body,\u000a        headers={"Content-Type": "application/json"},\u000a        method="POST",\u000a    )\u000a    try:\u000a        with urllib.request.urlopen(req, timeout=30) as resp:\u000a            return json.loads(resp.read())\u000a    except urllib.error.URLError as e:\u000a        return {"status": "error", "message": f"Server connection failed: {e}"}\u000a    except Exception as e:\u000a        return {"status": "error", "message": str(e)}\u000a\u000a\u000adef main():\u000a    parser = argparse.ArgumentParser()\u000a    parser.add_argument("--action", required=True)\u000a    parser.add_argument("--url", default="")\u000a    parser.add_argument("--text", default="")\u000a    parser.add_argument("--selector", default="")\u000a    parser.add_argument("--submit", action="store_true")\u000a    parser.add_argument("--direction", default="down")\u000a    parser.add_argument("--amount", type=int, default=500)\u000a    parser.add_argument("--timeout", type=int, default=15000)\u000a    parser.add_argument("--navigate", action="store_true") # For get_links auto-navigation\u000a    parser.add_argument("--x", type=float, default=None)\u000a    parser.add_argument("--y", type=float, default=None)\u000a    args = parser.parse_args()\u000a\u000a    # Ensure daemon is running\u000a    if not is_server_alive():\u000a        if not start_server():\u000a            print(json.dumps({"status": "error", "message": "Could not start browser daemon"}))\u000a            sys.exit(1)\u000a\u000a    payload = {\u000a        "action": args.action,\u000a        "url": args.url,\u000a        "text": args.text,\u000a        "selector": args.selector,\u000a        "submit": args.submit,\u000a        "direction": args.direction,\u000a        "amount": args.amount,\u000a        "timeout": args.timeout,\u000a        "auto_navigate": args.navigate,\u000a        "x": args.x,\u000a        "y": args.y,\u000a    }\u000a\u000a    result = send_action(payload)\u000a\u000a    # Human-readable status line to stdout (for the agent log)\u000a    status = result.get("status", "?")\u000a    title  = result.get("title", "")\u000a    url    = result.get("url", "")\u000a\u000a    if args.action == "search":\u000a        if status == "error":\u000a            print(f"❌ Search failed: {result.get(''message'', ''Unknown error'')}")\u000a        else:\u000a            print(f"✅ Search complete: ''{title}'' @ {url}")\u000a    elif args.action == "click":\u000a        if status == "clicked":\u000a            print(f"✅ Clicked. Now at: ''{title}'' @ {url}")\u000a        else:\u000a            print(f"⚠️ Click result: {result.get(''message'', status)}")\u000a    elif args.action == "navigate":\u000a        print(f"✅ Navigated to: ''{title}'' @ {url}")\u000a    elif args.action == "get_links":\u000a        if status == "navigated":\u000a            print(f"✅ Found matches and Navigated to: ''{title}'' @ {url}")\u000a        else:\u000a            links = result.get("links", [])\u000a            print(f"✅ Found {len(links)} links:")\u000a            for l in links[:10]:\u000a                print(f"  [{l.get(''text'','''')[:60]}] -> {l.get(''href'','''')[:80]}")\u000a    elif args.action == "get_title":\u000a        print(f"📄 ''{title}'' @ {url}")\u000a    else:\u000a        print(f"✅ {args.action}: {status}")\u000a\u000a    # Always also print the full JSON for the Rust side to parse\u000a    print(json.dumps(result))\u000a\u000a\u000aif __name__ == "__main__":\u000a    main()\u000a'),'python','1.0.0',NULL,'2026-03-14 06:42:50','2026-03-14 06:42:50','agents-scripts/web/browser_automation.py',NULL);
INSERT INTO tools VALUES(7438474706690379777,'stealth_search','stealth_search: Accept a raw search query string as input. Return search results with URLs and snippets.',unistr('#!/usr/bin/env python3\u000aimport sys\u000aimport requests\u000aimport json\u000afrom bs4 import BeautifulSoup\u000a\u000adef search_ddg_stealth(query):\u000a    # Use DuckDuckGo HTML version for scraping (lite/html)\u000a    url = "https://html.duckduckgo.com/html/"\u000a    headers = {\u000a        "User-Agent": "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36"\u000a    }\u000a    \u000a    try:\u000a        response = requests.post(url, data={"q": query}, headers=headers, timeout=10)\u000a        response.raise_for_status()\u000a        \u000a        soup = BeautifulSoup(response.text, "html.parser")\u000a        results = []\u000a        \u000a        for item in soup.select(".result"):\u000a            title_el = item.select_one(".result__a")\u000a            snippet_el = item.select_one(".result__snippet")\u000a            \u000a            if title_el:\u000a                title = title_el.get_text(strip=True)\u000a                href = title_el.get("href")\u000a                snippet = snippet_el.get_text(strip=True) if snippet_el else ""\u000a                \u000a                results.append({\u000a                    "title": title,\u000a                    "url": href,\u000a                    "snippet": snippet\u000a                })\u000a        \u000a        return results[:5]\u000a    except Exception as e:\u000a        return {"error": str(e)}\u000a\u000aif __name__ == "__main__":\u000a    if len(sys.argv) < 2:\u000a        print(json.dumps({"error": "No query provided"}))\u000a        sys.exit(1)\u000a        \u000a    query = " ".join(sys.argv[1:])\u000a    results = search_ddg_stealth(query)\u000a    print(json.dumps(results, indent=2))\u000a'),'python','1.0.0',NULL,'2026-03-14 06:42:50','2026-03-14 06:42:50','agents-scripts/stealth/stealth_search.py',NULL);
INSERT INTO tools VALUES(7438474706690379778,'stealth_browse','stealth_browse: Accept a raw URL string as input (e.g. "https://nextjs.org"). Fetch and return cleaned text content.',unistr('#!/usr/bin/env python3\u000aimport sys\u000aimport requests\u000aimport json\u000afrom bs4 import BeautifulSoup\u000aimport re\u000a\u000adef get_page_text(url):\u000a    headers = {\u000a        "User-Agent": "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36"\u000a    }\u000a    \u000a    try:\u000a        response = requests.get(url, headers=headers, timeout=15)\u000a        response.raise_for_status()\u000a        \u000a        soup = BeautifulSoup(response.text, "html.parser")\u000a        \u000a        # Remove script and style elements\u000a        for script_or_style in soup(["script", "style", "header", "footer", "nav"]):\u000a            script_or_style.decompose()\u000a            \u000a        # Get text\u000a        text = soup.get_text(separator='' '')\u000a        \u000a        # Clean up whitespace\u000a        lines = (line.strip() for line in text.splitlines())\u000a        chunks = (phrase.strip() for line in lines for phrase in line.split("  "))\u000a        text = ''\\n''.join(chunk for chunk in chunks if chunk)\u000a        \u000a        # Limit total length to fit in Rig outputs sensibly, but much more than 10KB raw HTML\u000a        # We can afford more text if it''s clean text.\u000a        return text[:15000] \u000a    except Exception as e:\u000a        return f"Error fetching {url}: {str(e)}"\u000a\u000aif __name__ == "__main__":\u000a    if len(sys.argv) < 2:\u000a        print("Usage: stealth_browse.py <url>")\u000a        sys.exit(1)\u000a        \u000a    url = sys.argv[1]\u000a    result = get_page_text(url)\u000a    print(result)\u000a'),'python','1.0.0',NULL,'2026-03-14 06:42:50','2026-03-14 06:42:50','agents-scripts/stealth/stealth_browse.py',NULL);
INSERT INTO tools VALUES(7438474706694574080,'calibrate','calibrate tool for desktop domain',unistr('import pyautogui\u000aimport time\u000aimport json\u000aimport sys\u000aimport os\u000a\u000aCONFIG_FILE = os.path.expanduser("~/.neontune_config.json")\u000a\u000adef calibrate():\u000a    print("🎯 Neontune Calibration Tool")\u000a    print("--------------------------------")\u000a    print("We need to teach the agent where the UI elements are.")\u000a    print("Move your mouse to the target and press ENTER in this terminal.")\u000a    \u000a    try:\u000a        # 1. Search Bar\u000a        input("\\n1. Hover over the **Search Bar** (text input) and press ENTER...")\u000a        sx, sy = pyautogui.position()\u000a        print(f"   Captured: {sx}, {sy}")\u000a        \u000a        # 2. First Result\u000a        input("\\n2. Type a search, wait for results, then hover over the **First Song Row** and press ENTER...")\u000a        rx, ry = pyautogui.position()\u000a        print(f"   Captured: {rx}, {ry}")\u000a        \u000a        config = {\u000a            "search": [sx, sy],\u000a            "result": [rx, ry]\u000a        }\u000a        \u000a        with open(CONFIG_FILE, "w") as f:\u000a            json.dump(config, f)\u000a            \u000a        print(f"\\n✅ Configuration saved to {CONFIG_FILE}")\u000a        print("Automation attempts will now use these exact coordinates automatically.")\u000a        \u000a    except KeyboardInterrupt:\u000a        print("\\nCalibration cancelled.")\u000a        sys.exit(1)\u000a\u000aif __name__ == "__main__":\u000a    calibrate()\u000a'),'python','1.0.0',NULL,'2026-03-14 06:42:50','2026-03-14 06:42:50','agents-scripts/desktop/calibrate.py',NULL);
INSERT INTO tools VALUES(7438474706694574081,'diagnose_ui','diagnose_ui tool for desktop domain',unistr('import subprocess\u000aimport time\u000aimport os\u000a\u000adef run_diagnosis():\u000a    # 1. Launch/Check\u000a    print("🚀 Launching/Checking Neontune...")\u000a    subprocess.Popen(["neontune"])\u000a    time.sleep(4)\u000a    \u000a    window_name = "tao window"\u000a    \u000a    # 2. Debug Layout\u000a    print("📋 Current Window List (wmctrl -lG):")\u000a    subprocess.run(["wmctrl", "-lG"])\u000a    \u000a    # 3. Force Focus (Aggressive)\u000a    print(f"🎯 Focusing {window_name}...")\u000a    subprocess.run(["wmctrl", "-a", window_name], check=False)\u000a    time.sleep(0.5)\u000a    \u000a    # xdotool activate\u000a    try:\u000a        wid = subprocess.check_output([''xdotool'', ''search'', ''--name'', ''--limit'', ''1'', window_name]).decode().strip()\u000a        print(f"✅ Found Window ID: {wid}")\u000a        subprocess.run([''xdotool'', ''windowactivate'', ''--sync'', wid])\u000a    except Exception as e:\u000a        print(f"⚠️ xdotool failed: {e}")\u000a\u000a    # 4. Reset Layout (Force 0,0) after focus\u000a    print(f"📏 Resetting layout...")\u000a    subprocess.run(["wmctrl", "-r", window_name, "-e", "0,0,0,1280,800"], check=False)\u000a    time.sleep(1)\u000a    \u000a    # 5. Screenshot\u000a    print("📸 Taking screenshot...")\u000a    subprocess.run(["import", "-window", "root", "ui_debug.png"])\u000a    \u000a    # 6. OCR\u000a    print("🔍 Running OCR...")\u000a    subprocess.run(["tesseract", "ui_debug.png", "ui_debug_ocr", "hocr"])\u000a    \u000a    # 7. Parse\u000a    print("📊 Extracting word coordinates...")\u000a    subprocess.run(["python3", "scripts/ocr_dump.py"])\u000a\u000aif __name__ == "__main__":\u000a    run_diagnosis()\u000a'),'python','1.0.0',NULL,'2026-03-14 06:42:50','2026-03-14 06:42:50','agents-scripts/desktop/diagnose_ui.py',NULL);
INSERT INTO tools VALUES(7438474706694574082,'configure_app','configure_app tool for desktop domain',unistr('#!/usr/bin/env python3\u000aimport pyautogui\u000aimport json\u000aimport os\u000aimport argparse\u000aimport time\u000a\u000aCONFIG_PATH = os.path.expanduser("~/.config/rig/apps.json")\u000a\u000adef load_config():\u000a    if os.path.exists(CONFIG_PATH):\u000a        try:\u000a            with open(CONFIG_PATH, ''r'') as f:\u000a                return json.load(f)\u000a        except:\u000a            pass\u000a    return {}\u000a\u000adef save_config(config):\u000a    os.makedirs(os.path.dirname(CONFIG_PATH), exist_ok=True)\u000a    with open(CONFIG_PATH, ''w'') as f:\u000a        json.dump(config, f, indent=4)\u000a    print(f"✅ Configuration saved to {CONFIG_PATH}")\u000a\u000adef configure(app_name):\u000a    print(f"\\n🔧 Configuring ''{app_name}'' automation profile.")\u000a    print("------------------------------------------------")\u000a    print("We need to teach the agent where the Search Bar and Results are.")\u000a    print("Launch the app manually and arrange it how you like (or let the agent reset it later).")\u000a    print("NOTE: It is best if the app is maximized or in a standard position.\\n")\u000a\u000a    input(f"1. Open ''{app_name}'' and Hover mouse over the **SEARCH BAR**. Press ENTER when ready...")\u000a    sx, sy = pyautogui.position()\u000a    print(f"   📍 Captured Search: {sx}, {sy}")\u000a    \u000a    time.sleep(1)\u000a    \u000a    input(f"2. Type a search (e.g. ''Test'') and Hover over the **FIRST RESULT**. Press ENTER when ready...")\u000a    rx, ry = pyautogui.position()\u000a    print(f"   📍 Captured Result: {rx}, {ry}")\u000a\u000a    # Load existing\u000a    config = load_config()\u000a    profile = config.get(app_name.lower(), {})\u000a    \u000a    # Update profile\u000a    profile["window_title"] = app_name # User can edit json later if complex\u000a    profile["launch_cmd"] = [app_name.lower()]\u000a    profile["search_pos"] = [sx, sy]\u000a    profile["result_pos"] = [rx, ry]\u000a    # Default to NO reset if user is calibrating manually, \u000a    # OR we assume they want the reset behavior? \u000a    # Let''s ask? No, keep it simple. Enable reset for consistency.\u000a    profile["reset_layout"] = True \u000a\u000a    config[app_name.lower()] = profile\u000a    save_config(config)\u000a    print(f"\\n✨ Setup Complete for {app_name}!")\u000a    print(f"You can now run: cargo run -- \\"play ''Song'' in {app_name}\\"")\u000a\u000aif __name__ == "__main__":\u000a    parser = argparse.ArgumentParser()\u000a    parser.add_argument("--app", required=True, help="App name to configure")\u000a    args = parser.parse_args()\u000a    \u000a    configure(args.app)\u000a'),'python','1.0.0',NULL,'2026-03-14 06:42:50','2026-03-14 06:42:50','agents-scripts/desktop/configure_app.py',NULL);
INSERT INTO tools VALUES(7438474706694574083,'paddle_ui_automation','paddle_ui_automation tool for desktop domain',X'','python','1.0.0',NULL,'2026-03-14 06:42:50','2026-03-14 06:42:50','agents-scripts/desktop/paddle_ui_automation.py',NULL);
INSERT INTO tools VALUES(7438474706694574084,'verify_layout','verify_layout tool for desktop domain',unistr('import sys\u000aimport time\u000aimport subprocess\u000aimport pyautogui\u000aimport os\u000a\u000a# Reuse functions from ui_automation.py implicitly or re-define\u000adef reset_window_layout(window_name="tao window"):\u000a    print(f"📏 Resetting ''{window_name}''...")\u000a    subprocess.run(["wmctrl", "-r", window_name, "-b", "remove,maximized_vert,maximized_horz,fullscreen"], check=False)\u000a    subprocess.run(["wmctrl", "-r", window_name, "-e", "0,0,0,1280,800"], check=True)\u000a    subprocess.run(["wmctrl", "-R", window_name], check=True)\u000a    time.sleep(1)\u000a\u000adef run_debug(text):\u000a    # 1. Launch/Focus\u000a    print(f"🚀 Launching/Focusing Neontune...")\u000a    subprocess.Popen(["neontune"])\u000a    time.sleep(2)\u000a    reset_window_layout("tao window")\u000a    \u000a    # 2. Click Search (400, 100)\u000a    print("🖱️ Clicking Search (400, 100)")\u000a    pyautogui.click(400, 100)\u000a    time.sleep(0.5)\u000a    \u000a    # 3. Type\u000a    print(f"⌨️ Typing ''{text}''...")\u000a    pyautogui.hotkey(''ctrl'', ''a'')\u000a    pyautogui.press(''backspace'')\u000a    pyautogui.write(text, interval=0.1)\u000a    pyautogui.press(''enter'')\u000a    \u000a    # 4. Wait\u000a    print("⏳ Waiting 3s for results...")\u000a    time.sleep(3)\u000a    \u000a    # 5. Screenshot\u000a    print("📸 Taking debug screenshot...")\u000a    subprocess.run(["import", "-window", "root", "neontune_debug.png"])\u000a    \u000a    # 6. OCR interactively?\u000a    # We will let the agent run tesseract separately\u000a    print("✅ Done. Check neontune_debug.png")\u000a\u000aif __name__ == "__main__":\u000a    run_debug("Tali Rush - U")\u000a'),'python','1.0.0',NULL,'2026-03-14 06:42:50','2026-03-14 06:42:50','agents-scripts/desktop/verify_layout.py',NULL);
INSERT INTO tools VALUES(7438474706694574085,'find_search_field','find_search_field tool for desktop domain',unistr('#!/usr/bin/env python3\u000a"""\u000aTest script to find the correct search field coordinates in Neontune.\u000aThis will click different locations and wait for you to verify which one worked.\u000a"""\u000a\u000aimport pyautogui\u000aimport subprocess\u000aimport time\u000a\u000a# Launch Neontune\u000aprint("🚀 Launching Neontune...")\u000asubprocess.Popen([''neontune''])\u000atime.sleep(3)\u000a\u000a# Test different coordinates\u000atest_coords = [\u000a    (400, 100, "Top center"),\u000a    (500, 150, "Slightly right and down"),\u000a    (300, 100, "Slightly left"),\u000a    (400, 80, "Higher up"),\u000a    (400, 120, "Lower down"),\u000a]\u000a\u000afor x, y, desc in test_coords:\u000a    print(f"\\n🖱️ Clicking {desc} at ({x}, {y})")\u000a    print("   Watch where the cursor goes...")\u000a    pyautogui.click(x, y)\u000a    time.sleep(2)\u000a    \u000a    response = input("   Did this click the search field? (y/n): ")\u000a    if response.lower() == ''y'':\u000a        print(f"\\n✅ Found it! Search field is at ({x}, {y})")\u000a        print(f"   Update ui_automation.py line 83: click_search_field({x}, {y})")\u000a        break\u000aelse:\u000a    print("\\n❌ None of the coordinates worked.")\u000a    print("   The search field might be in a different location.")\u000a    print("   Try running: xdotool getmouselocation")\u000a    print("   Then hover over the search field and note the coordinates.")\u000a'),'python','1.0.0',NULL,'2026-03-14 06:42:50','2026-03-14 06:42:50','agents-scripts/desktop/find_search_field.py',NULL);
INSERT INTO tools VALUES(7438474706694574086,'verify_window_capture','verify_window_capture tool for desktop domain',unistr('import subprocess\u000aimport time\u000aimport os\u000a\u000adef check_capture():\u000a    print("🔍 Searching for ''tao'' window...")\u000a    try:\u000a        # Find window ID\u000a        wid_bytes = subprocess.check_output([''xdotool'', ''search'', ''--name'', ''tao''])\u000a        wids = wid_bytes.decode().strip().split(''\\n'')\u000a        \u000a        if not wids:\u000a            print("❌ No ''tao'' window found.")\u000a            return\u000a            \u000a        wid = wids[-1] # Take last one (usually the active one)\u000a        print(f"✅ Found Window ID: {wid}")\u000a        \u000a        # Get Geometry\u000a        geo = subprocess.check_output([''xdotool'', ''getwindowgeometry'', wid]).decode()\u000a        print(f"📏 Geometry:\\n{geo}")\u000a\u000a        # Capture SPECIFIC window\u000a        output_file = "neontune_window.png"\u000a        print(f"📸 Capturing Window {wid} to {output_file}...")\u000a        subprocess.run([''import'', ''-window'', wid, output_file])\u000a        \u000a        # OCR\u000a        print("📝 Running OCR...")\u000a        subprocess.run([''tesseract'', output_file, ''neontune_ocr'', ''hocr''])\u000a        subprocess.run([''cat'', ''neontune_ocr.hocr'']) # Dump raw for quick peek\u000a\u000a    except subprocess.CalledProcessError as e:\u000a        print(f"❌ Commands failed: {e}")\u000a    except Exception as e:\u000a        print(f"❌ Error: {e}")\u000a\u000aif __name__ == "__main__":\u000a    check_capture()\u000a'),'python','1.0.0',NULL,'2026-03-14 06:42:50','2026-03-14 06:42:50','agents-scripts/desktop/verify_window_capture.py',NULL);
INSERT INTO tools VALUES(7438474706694574087,'ocr_coordinates','ocr_coordinates tool for desktop domain',unistr('import sys\u000aimport re\u000aimport xml.etree.ElementTree as ET\u000a\u000adef find_all_coords(file_path, target_word):\u000a    coords_list = []\u000a    try:\u000a        tree = ET.parse(file_path)\u000a        root = tree.getroot()\u000a        for elem in root.iter():\u000a            if ''ocrx_word'' in (elem.get(''class'') or ""):\u000a                text = elem.text or ""\u000a                if target_word.lower() in text.lower():\u000a                    title = elem.get(''title'')\u000a                    match = re.search(r''bbox (\\d+) (\\d+) (\\d+) (\\d+)'', title)\u000a                    if match:\u000a                        x1, y1, x2, y2 = map(int, match.groups())\u000a                        cx, cy = (x1 + x2) // 2, (y1 + y2) // 2\u000a                        coords_list.append((cx, cy))\u000a    except Exception as e:\u000a        print(f"Error parsing HOCR: {e}")\u000a    return coords_list\u000a\u000aif __name__ == "__main__":\u000a    if len(sys.argv) < 2:\u000a        print("Usage: script.py <word>")\u000a        sys.exit(1)\u000a        \u000a    coords = find_all_coords("hocr_results.hocr", sys.argv[1])\u000a    for c in coords:\u000a        print(f"{c[0]} {c[1]}")\u000a'),'python','1.0.0',NULL,'2026-03-14 06:42:50','2026-03-14 06:42:50','agents-scripts/desktop/ocr_coordinates.py',NULL);
INSERT INTO tools VALUES(7438474706694574088,'vision_debug','vision_debug tool for desktop domain',unistr('import urllib.request\u000aimport json\u000aimport base64\u000aimport sys\u000a\u000adef analyze_image(image_path, prompt):\u000a    try:\u000a        with open(image_path, "rb") as f:\u000a            image_base64 = base64.b64encode(f.read()).decode("utf-8")\u000a    except FileNotFoundError:\u000a        return "Error: File not found"\u000a\u000a    url = "http://localhost:11434/api/generate"\u000a    data = {\u000a        "model": "qwen2.5vl:3b",\u000a        "prompt": prompt,\u000a        "images": [image_base64],\u000a        "stream": False, \u000a        "format": "json"\u000a    }\u000a\u000a    try:\u000a        req = urllib.request.Request(url, json.dumps(data).encode("utf-8"), headers={"Content-Type": "application/json"})\u000a        with urllib.request.urlopen(req) as response:\u000a            return json.loads(response.read().decode("utf-8"))["response"]\u000a    except Exception as e:\u000a        return f"Request failed: {e}"\u000a\u000aprint("Analyzing Search Field...")\u000a# Ask for specific point format\u000aprint(analyze_image("screenshot.png", "Return a JSON object with a single key ''point'' containing [x, y] coordinates for the center of the search input field in the application window."))\u000a\u000aprint("\\nAnalyzing First Result...")\u000aprint(analyze_image("screenshot.png", "Return a JSON object with a single key ''point'' containing [x, y] coordinates for the center of the first song row in the list below the search bar."))\u000a'),'python','1.0.0',NULL,'2026-03-14 06:42:50','2026-03-14 06:42:50','agents-scripts/desktop/vision_debug.py',NULL);
INSERT INTO tools VALUES(7438474706694574089,'ui_automation','ui_automation tool for desktop domain',unistr('#!/usr/bin/env python3\u000a"""\u000aAdaptive UI Automation script using OCR.\u000aFinds ''Search'' and specific text on screen dynamically.\u000a"""\u000a\u000aimport sys\u000aimport time\u000aimport subprocess\u000aimport pyautogui\u000aimport argparse\u000aimport os\u000aimport re\u000aimport json\u000aimport hashlib\u000aimport tempfile\u000a# --- PADDLEOCR INTEGRATION ---\u000a# Always use PaddleOCR as requested by the user. \u000aos.environ["PADDLE_PDX_DISABLE_MODEL_SOURCE_CHECK"] = "True"\u000aos.environ["FLAGS_use_onednn"] = "0"\u000aos.environ["FLAGS_use_mkldnn"] = "0"\u000a\u000atry:\u000a    from paddleocr import PaddleOCR\u000a    # Final production-grade initialization\u000a    paddle_ocr_engine = PaddleOCR(lang=''en'', use_angle_cls=False, use_gpu=False, show_log=False)\u000a    print("🌀 Initialized PaddleOCR engine backend.", file=sys.stderr)\u000aexcept Exception as e:\u000a    print(f"❌ CRITICAL: Failed to init PaddleOCR: {e}. Automation will fail.", file=sys.stderr)\u000a    sys.exit(1)\u000a\u000aimport gi\u000atry:\u000a    gi.require_version(''Atspi'', ''2.0'')\u000a    from gi.repository import Atspi\u000aexcept ImportError:\u000a    Atspi = None\u000aexcept ValueError:\u000a    Atspi = None\u000a\u000a# Disable pyautogui failsafe for automation\u000apyautogui.FAILSAFE = False\u000a\u000a\u000a# word_pattern = re.compile(r''title=[\\''"]bbox (\\d+) (\\d+) (\\d+) (\\d+);?\\s*x_wconf \\d+[\\''"]>\\s*([^<]+)\\s*</span>'')\u000a\u000aDEBUG_DRAW = False\u000a\u000aCONFIG_PATH = os.path.expanduser("~/.config/rig/apps.json")\u000a\u000adef load_config():\u000a    if os.path.exists(CONFIG_PATH):\u000a        try:\u000a            with open(CONFIG_PATH, ''r'') as f:\u000a                return json.load(f)\u000a        except:\u000a            pass\u000a    return {}\u000a\u000adef get_window_geometry(wid):\u000a    """Returns (x, y, width, height) of the window."""\u000a    try:\u000a        out = subprocess.check_output([''xdotool'', ''getwindowgeometry'', str(wid)]).decode()\u000a        # Window 83886092\u000a        #   Position: 166,132 (screen: 0)\u000a        #   Geometry: 800x600\u000a        pos_line = [l for l in out.split(''\\n'') if ''Position:'' in l][0]\u000a        geo_line = [l for l in out.split(''\\n'') if ''Geometry:'' in l][0]\u000a        \u000a        x, y = map(int, re.search(r''Position: (\\d+),(\\d+)'', pos_line).groups())\u000a        w, h = map(int, re.search(r''Geometry: (\\d+)x(\\d+)'', geo_line).groups())\u000a        return x, y, w, h\u000a    except:\u000a        return 0, 0, 0, 0\u000a\u000adef get_window_id(window_title):\u000a    try:\u000a        # Get all IDs matching the name\u000a        out = subprocess.check_output([''xdotool'', ''search'', ''--name'', window_title])\u000a        wids = out.decode().strip().split(''\\n'')\u000a        \u000a        if not wids: return None\u000a        \u000a        # Filter: Find the LARGEST window (Main Application Window)\u000a        best_wid = None\u000a        max_area = 0\u000a        \u000a        for wid in wids:\u000a            try:\u000a                _, _, w, h = get_window_geometry(wid)\u000a                area = w * h\u000a                # Ignore tiny windows (tooltips, invisible proxies)\u000a                if area > max_area and w > 200 and h > 200:\u000a                    max_area = area\u000a                    best_wid = wid\u000a            except:\u000a                continue\u000a                \u000a        # Fallback: If no "large" window found, return the last one (legacy behavior)\u000a        return best_wid if best_wid else wids[-1]\u000a    except:\u000a        return None\u000a\u000a\u000adef get_screen_text(app_name, grep_str=None):\u000a    """Captures window and returns JSON list of all text with coords, optionally filtering."""\u000a    print(f"📖 Reading screen text for {app_name} (grep: {grep_str})...", file=sys.stderr)\u000a    \u000a    wid = None\u000a    if app_name.lower() == "active":\u000a        try:\u000a            wid = subprocess.check_output([''xdotool'', ''getactivewindow'']).decode().strip()\u000a        except:\u000a            pass\u000a    else:\u000a        config = load_config()\u000a        profile = config.get(app_name.lower(), {})\u000a        win_title = resolve_window_title(app_name, config)\u000a        wid = focus_window(win_title)\u000a\u000a    if not wid:\u000a        print(f"❌ Could not focus {app_name}.")\u000a        return json.dumps({"error": "Window not found"})\u000a        \u000a    time.sleep(0.5)\u000a    \u000a    win_x, win_y, _, _ = get_window_geometry(wid)\u000a    \u000a    try:\u000a        tmp_img = "/tmp/rig_ui_capture.png"\u000a        subprocess.run([''import'', ''-window'', wid, tmp_img], check=True)\u000a        \u000a        words = []\u000a        if paddle_ocr_engine:\u000a            # Use PaddleOCR backend (EXCLUSIVE)\u000a            result = paddle_ocr_engine.ocr(tmp_img)\u000a            if result and result[0]:\u000a                for line in result[0]:\u000a                    if not line or len(line) < 2: continue\u000a                    points = line[0] # [[x1, y1], [x2, y1], [x2, y2], [x1, y2]]\u000a                    text = line[1][0]\u000a                    conf = line[1][1]\u000a                    \u000a                    x0 = int(min(p[0] for p in points))\u000a                    y0 = int(min(p[1] for p in points))\u000a                    x1 = int(max(p[0] for p in points))\u000a                    y1 = int(max(p[1] for p in points))\u000a                    \u000a                    words.append({\u000a                        "text": text.strip(),\u000a                        "x0": x0, "y0": y0,\u000a                        "x1": x1, "y1": y1,\u000a                        "confidence": float(conf)\u000a                    })\u000a        else:\u000a             return json.dumps({"error": "PaddleOCR engine unavailable."})\u000a\u000a        lines = []\u000a        \u000a        words.sort(key=lambda w: (w["y0"], w["x0"]))\u000a\u000a        for word in words:\u000a            if grep_str and grep_str.lower() not in word["text"].lower():\u000a                continue\u000a                \u000a            # Find a line that this word belongs to (vertical overlap)\u000a            placed = False\u000a            for line in lines:\u000a                # Vertical overlap threshold: at least 50% overlap or within 5 pixels\u000a                line_y_mid = (line["y0"] + line["y1"]) // 2\u000a                word_y_mid = (word["y0"] + word["y1"]) // 2\u000a                \u000a                if abs(line_y_mid - word_y_mid) < 8: # Pixels tolerance for same line\u000a                    line["words"].append(word)\u000a                    line["y0"] = min(line["y0"], word["y0"])\u000a                    line["y1"] = max(line["y1"], word["y1"])\u000a                    line["x0"] = min(line["x0"], word["x0"])\u000a                    line["x1"] = max(line["x1"], word["x1"])\u000a                    placed = True\u000a                    break\u000a            \u000a            if not placed:\u000a                lines.append({\u000a                    "words": [word],\u000a                    "y0": word["y0"], "y1": word["y1"],\u000a                    "x0": word["x0"], "x1": word["x1"]\u000a                })\u000a\u000a        final_results = []\u000a        for line in lines:\u000a            sorted_words = sorted(line["words"], key=lambda w: w["x0"])\u000a            full_text = " ".join([w["text"] for w in sorted_words])\u000a            \u000a            # If grep_str is provided, try to find the specific matching word(s) in the line\u000a            # to be more precise with the click.\u000a            target_x, target_y = None, None\u000a            \u000a            if grep_str:\u000a                # Simple check: if the line contains the text, verify which words match\u000a                # This is a heuristic. For now, we still return the line center,\u000a                # but we could refine this to return the center of the MATCHING substring.\u000a                pass\u000a\u000a            # Default: Center of the line/block\u000a            target_x = win_x + (line["x0"] + line["x1"]) // 2\u000a            target_y = win_y + (line["y0"] + line["y1"]) // 2\u000a            \u000a            # If searching for specific text, try to find the center of the matching words\u000a            if grep_str and grep_str.lower() in full_text.lower():\u000a                 # Filter words that are part of the match\u000a                 matching_words = [w for w in sorted_words if w["text"].lower() in grep_str.lower() or grep_str.lower() in w["text"].lower()]\u000a                 if matching_words:\u000a                     min_x = min(w["x0"] for w in matching_words)\u000a                     max_x = max(w["x1"] for w in matching_words)\u000a                     min_y = min(w["y0"] for w in matching_words)\u000a                     max_y = max(w["y1"] for w in matching_words)\u000a                     target_x = win_x + (min_x + max_x) // 2\u000a                     target_y = win_y + (min_y + max_y) // 2\u000a\u000a            final_results.append({\u000a                "text": full_text,\u000a                "x": target_x,\u000a                "y": target_y,\u000a                "width": line["x1"] - line["x0"],\u000a                "height": line["y1"] - line["y0"]\u000a            })\u000a                \u000a        return json.dumps(final_results)\u000a    except Exception as e:\u000a        return json.dumps({"error": str(e)})\u000a\u000adef find_text_matches(wid, target_text):\u000a    """\u000a    Captures window, runs OCR, returns list of (cx, cy, word) relative to SCREEN.\u000a    """\u000a    try:\u000a        tmp_img = "/tmp/rig_ui_capture.png"\u000a        subprocess.run([''import'', ''-window'', wid, tmp_img], check=True)\u000a        \u000a        target_lower = target_text.lower()\u000a        win_x, win_y, _, _ = get_window_geometry(wid)\u000a        results = []\u000a\u000a        if paddle_ocr_engine:\u000a            result = paddle_ocr_engine.ocr(tmp_img)\u000a            if result and result[0]:\u000a                for line in result[0]:\u000a                    if not line or len(line) < 2: continue\u000a                    points = line[0]\u000a                    text = line[1][0]\u000a                    if target_lower in text.lower():\u000a                        x0 = min(p[0] for p in points)\u000a                        y0 = min(p[1] for p in points)\u000a                        x1 = max(p[0] for p in points)\u000a                        y1 = max(p[1] for p in points)\u000a                        cx = (x0 + x1) // 2\u000a                        cy = (y0 + y1) // 2\u000a                        screen_x = win_x + cx\u000a                        screen_y = win_y + cy\u000a                        results.append((int(screen_x), int(screen_y), text))\u000a                        print(f"👁️ [Paddle] Found candidate ''{text}'' at Screen({screen_x},{screen_y})")\u000a        else:\u000a            print("❌ PaddleOCR engine not initialized.")\u000a\u000a        return results\u000a    except Exception as e:\u000a        print(f"❌ Vision error: {e}")\u000a        return []\u000a\u000adef capture_and_find_text(wid, target_text):\u000a    """Legacy wrapper: Returns first match (cx, cy) or (None, None)."""\u000a    matches = find_text_matches(wid, target_text)\u000a    if matches:\u000a        return matches[0][0], matches[0][1]\u000a    return None, None\u000a\u000adef focus_window(window_title):\u000a    print(f"🎯 Focusing ''{window_title}''...", file=sys.stderr)\u000a    # 1. Try direct match\u000a    subprocess.run([''wmctrl'', ''-a'', window_title], check=False)\u000a    wid = get_window_id(window_title)\u000a    \u000a    # 2. If not found, try case-insensitive search\u000a    if not wid:\u000a        try:\u000a            output = subprocess.check_output([''wmctrl'', ''-l'']).decode(''utf-8'')\u000a            for line in output.splitlines():\u000a                parts = line.split(maxsplit=3)\u000a                if len(parts) > 3:\u000a                     current_wid = parts[0]\u000a                     current_title = " ".join(parts[3:]) if len(parts) > 3 else parts[3]\u000a                     if window_title.lower() in current_title.lower():\u000a                         print(f"🎯 Found partial match: ''{current_title}''")\u000a                         subprocess.run([''wmctrl'', ''-ia'', current_wid], check=False)\u000a                         # wmctrl gives hex ID (e.g. 0x01a00003), xdotool needs decimal.\u000a                         # Instead of re-searching by name, just convert to decimal!\u000a                         try:\u000a                             wid = str(int(current_wid, 16))\u000a                         except ValueError:\u000a                             wid = get_window_id(current_title) # Fallback to name search\u000a                         break\u000a        except Exception as e:\u000a            print(f"⚠️ Focus search error: {e}")\u000a\u000a    if wid:\u000a        subprocess.run([''xdotool'', ''windowactivate'', ''--sync'', wid], check=False)\u000a        subprocess.run([''xdotool'', ''windowraise'', wid], check=False)\u000a        return wid\u000a    \u000a    # 3. Last ditch effort: if app_name is likely a browser, try searching for "Chrome" or "Firefox"\u000a    if window_title.lower() in ["chrome", "google-chrome", "chromium"]:\u000a        for title in ["Google Chrome", "Chromium"]:\u000a            wid = get_window_id(title)\u000a            if wid:\u000a                subprocess.run([''xdotool'', ''windowactivate'', ''--sync'', wid], check=False)\u000a                subprocess.run([''xdotool'', ''windowraise'', wid], check=False)\u000a                return wid\u000a                \u000a    return None\u000a\u000adef wait_for_text(app_name, text, timeout=20):\u000a    """Wait until specific text appears on screen"""\u000a    print(f"⏳ Waiting for text ''{text}'' in {app_name} (timeout={timeout}s)...")\u000a    start_time = time.time()\u000a    while time.time() - start_time < timeout:\u000a        screen_text = get_screen_text(app_name)\u000a        if text.lower() in screen_text.lower():\u000a            print(f"✅ Found text ''{text}''!")\u000a            return True\u000a        time.sleep(2)\u000a    print(f"❌ Timeout waiting for ''{text}''")\u000a    return False\u000a\u000adef get_atspi_tree(app_name):\u000a    """\u000a    Query the Linux Accessibility Tree (AT-SPI2) for the specified application.\u000a    Returns a list of actionable UI elements with coordinates.\u000a    """\u000a    if Atspi is None:\u000a        return json.dumps({"error": "Atspi not available. Please install python3-gi and at-spi2-core."})\u000a\u000a    Atspi.init()\u000a    desktop = Atspi.get_desktop(0)\u000a    if not desktop:\u000a        return json.dumps({"error": "Could not connect to Atspi desktop"})\u000a\u000a    target_app = None\u000a    app_name_lower = app_name.lower() if app_name else ""\u000a\u000a    if not app_name or app_name_lower == "active":\u000a        # Get the currently focused window\u000a        # Note: Atspi.get_desktop(0) has get_active_window? \u000a        # Actually it''s simpler to iterate and find the one with ''active'' state, \u000a        # but let''s try to match the window title from xdotool if we can.\u000a        # For robustness, let''s search for the window that has STATE_ACTIVE\u000a        for i in range(desktop.get_child_count()):\u000a            app = desktop.get_child_at_index(i)\u000a            if not app: continue\u000a            for j in range(app.get_child_count()):\u000a                win = app.get_child_at_index(j)\u000a                if not win: continue\u000a                try:\u000a                    states = win.get_state_set().get_states()\u000a                    if Atspi.StateType.ACTIVE in states:\u000a                        target_app = app # We want the App, not just the window, usually\u000a                        # But actually we want to crawl the window.\u000a                        # Let''s return the app for now as the root.\u000a                        break\u000a                except: pass\u000a            if target_app: break\u000a            \u000a        if not target_app:\u000a             return json.dumps({"error": "No active window found and no app name provided."})\u000a    else:\u000a        # Find the application in the desktop tree by name\u000a        for i in range(desktop.get_child_count()):\u000a            child = desktop.get_child_at_index(i)\u000a            if not child: continue\u000a            \u000a            child_name = (child.get_name() or "").lower()\u000a            if app_name_lower in child_name or child_name in app_name_lower:\u000a                target_app = child\u000a                break\u000a\u000a    if not target_app:\u000a        # Fallback: Deep search for window title\u000a        print(f"⚠️ App ''{app_name}'' not found by name, deep searching...", file=sys.stderr)\u000a        for i in range(desktop.get_child_count()):\u000a            child = desktop.get_child_at_index(i)\u000a            if not child: continue\u000a            for j in range(child.get_child_count()):\u000a                grandchild = child.get_child_at_index(j)\u000a                if not grandchild: continue\u000a                grand_name = (grandchild.get_name() or "").lower()\u000a                if app_name_lower in grand_name:\u000a                    target_app = child\u000a                    break\u000a            if target_app: break\u000a\u000a    if not target_app:\u000a        return [] # Return empty list, caller will fallback to OCR\u000a\u000a    elements = []\u000a    \u000a    # Get window bounds for viewport tagging\u000a    win_x, win_y, win_w, win_h = 0, 0, 1920, 1080 # Fallback\u000a    try:\u000a        # If active window, try to find the actual window node to get its extents\u000a        for i in range(target_app.get_child_count()):\u000a            child = target_app.get_child_at_index(i)\u000a            if not child: continue\u000a            role = child.get_role_name()\u000a            if role in ["frame", "window"]:\u000a                comp = child.get_component_iface()\u000a                if comp:\u000a                    bbox = comp.get_extents(Atspi.CoordType.SCREEN)\u000a                    if bbox.width > 1:\u000a                        win_x, win_y, win_w, win_h = bbox.x, bbox.y, bbox.width, bbox.height\u000a                        break\u000a    except: pass\u000a\u000a    def crawl(obj, depth=0, path=""):\u000a        if depth > 15: return # Safety limit\u000a\u000a        try:\u000a            name = (obj.get_name() or "").strip()\u000a            role = obj.get_role_name()\u000a            \u000a            new_path = f"{path} > {role}" if path else role\u000a            \u000a            # Interesting roles for automation\u000a            interesting_roles = [\u000a                "push button", "text", "link", "menu item", "check box", \u000a                "radio button", "entry", "combo box", "toggle button", "page tab", "label",\u000a                "document", "web area", "heading", "list item"\u000a            ]\u000a            \u000a            container_roles = ["frame", "panel", "application", "window", "filler", "scroll pane", "layered pane", "root pane", "split pane"]\u000a\u000a            # Check visibility and state\u000a            state_set = obj.get_state_set()\u000a            is_visible = state_set.contains(Atspi.StateType.VISIBLE) if state_set else False\u000a            is_showing = state_set.contains(Atspi.StateType.SHOWING) if state_set else False\u000a            \u000a            # ALWAYS crawl containers, even if they report as invisible (Gtk boxes often do)\u000a            should_crawl_children = is_visible or is_showing or role in container_roles or role in ["document", "web area"]\u000a\u000a            if (role in interesting_roles or (name and len(name) > 0)) and (is_visible or is_showing):\u000a                # Get coordinates\u000a                try:\u000a                    comp = obj.get_component_iface()\u000a                    if comp:\u000a                        bbox = comp.get_extents(Atspi.CoordType.SCREEN)\u000a                        # Validate coordinates (Ignore off-screen/invalid junk)\u000a                        if bbox.width > 1 and bbox.height > 1 and bbox.x > -5000 and bbox.y > -5000:\u000a                            cx = bbox.x + bbox.width // 2\u000a                            cy = bbox.y + bbox.height // 2\u000a                            \u000a                            # VIEWPORT TAGGING\u000a                            visibility = "visible"\u000a                            if not (win_x <= cx <= win_x + win_w and win_y <= cy <= win_y + win_h):\u000a                                visibility = "off-screen"\u000a                                \u000a                            elements.append({\u000a                                "text": name,\u000a                                "role": role,\u000a                                "path": new_path,\u000a                                "x": cx,\u000a                                "y": cy,\u000a                                "width": bbox.width,\u000a                                "height": bbox.height,\u000a                                "visibility": visibility\u000a                            })\u000a                except:\u000a                    pass\u000a\u000a            if should_crawl_children:\u000a                # Recursively crawl children with "Lazy-Load Poke"\u000a                count = obj.get_child_count()\u000a                if count == 0 and depth < 3:\u000a                    # Some apps (Chrome) lazy load children. Poke them.\u000a                    time.sleep(0.05) # Shorter poke\u000a                    count = obj.get_child_count()\u000a\u000a                for k in range(count):\u000a                    child_obj = obj.get_child_at_index(k)\u000a                    if child_obj:\u000a                        crawl(child_obj, depth + 1, new_path)\u000a        except:\u000a            pass\u000a\u000a    crawl(target_app)\u000a    \u000a    # Chrome-specific: If we only got the frame, try a deeper poke\u000a    if len(elements) <= 1 and app_name_lower == "chrome":\u000a        # Force a refresh by looking for Document/Web Area\u000a        def force_poke(obj):\u000a            for i in range(obj.get_child_count()):\u000a                child = obj.get_child_at_index(i)\u000a                if child:\u000a                    role = child.get_role_name()\u000a                    if role in ["document", "web area", "page"]:\u000a                        return child\u000a                    res = force_poke(child)\u000a                    if res: return res\u000a            return None\u000a        \u000a        doc = force_poke(target_app)\u000a        if doc:\u000a            crawl(doc) # Recrawl from the document root\u000a\u000a    # Calculate Visual Hash using Screenshot\u000a    visual_hash = "0" * 32\u000a    try:\u000a        import hashlib\u000a        config = load_config()\u000a        profile = config.get(app_name.lower(), {})\u000a        win_title = resolve_window_title(app_name, config)\u000a        \u000a        # Try to match the currently found app if possible, or fall back to name\u000a        wid = None\u000a        if app_name.lower() == "active":\u000a             try:\u000a                 wid = subprocess.check_output([''xdotool'', ''getactivewindow'']).decode().strip()\u000a             except: pass\u000a        else:\u000a             wid = get_window_id(win_title)\u000a             if not wid and app_name.lower() == "chrome":\u000a                  wid = get_window_id("Google Chrome")\u000a\u000a        if wid:\u000a            tmp_shot = "/tmp/rig_visual_hash.png"\u000a            # Use import -window (fast)\u000a            subprocess.run([''import'', ''-window'', wid, ''-resize'', ''640x480'', tmp_shot], \u000a                         check=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)\u000a            \u000a            with open(tmp_shot, ''rb'') as f:\u000a                visual_hash = hashlib.md5(f.read()).hexdigest()\u000a    except Exception as e:\u000a        # print(f"⚠️ Visual hash failed: {e}", file=sys.stderr)\u000a        pass\u000a\u000a    return {\u000a        "elements": elements,\u000a        "visual_hash": visual_hash\u000a    }\u000a\u000adef get_state_delta(app_name, old_tree):\u000a    """\u000a    Returns what changed between old_tree and current tree.\u000a    """\u000a    new_tree = get_atspi_tree(app_name)\u000a    if "error" in new_tree: return new_tree\u000a    \u000a    old_elements = old_tree.get("elements", [])\u000a    new_elements = new_tree.get("elements", [])\u000a    \u000a    # Compare Visual Hashes First\u000a    if old_tree.get("visual_hash") != new_tree.get("visual_hash"):\u000a         # Visual change detected! Even if elements are same/similar.\u000a         # But wait, cursor blinking causes hash change?\u000a         # resizing 640x480 mitigates small noise, but blinking cursor might still trigger?\u000a         # Ideally we ignore small diffs. MD5 is strict.\u000a         # For now, let''s treat it as a "Potential Change".\u000a         pass\u000a\u000a    # Standard Element Diff\u000a    old_set = {f"{e[''role'']}:{e[''text'']}" for e in old_elements}\u000a    new_set = {f"{e[''role'']}:{e[''text'']}" for e in new_elements}\u000a    \u000a    added = [e for e in new_elements if f"{e[''role'']}:{e[''text'']}" not in old_set]\u000a    removed_count = len([e for e in old_elements if f"{e[''role'']}:{e[''text'']}" not in new_set])\u000a    \u000a    status = "Stable"\u000a    if added or removed_count > 0:\u000a        status = "Changed"\u000a        \u000a    return {\u000a        "status": status,\u000a        "added_count": len(added),\u000a        "added_preview": added[:5],\u000a        "removed_count": removed_count,\u000a        "visual_hash": new_tree.get("visual_hash")\u000a    }\u000a\u000adef search_in_app(app_name, query, no_launch=False):\u000a    """\u000a    Tries multiple strategies to search:\u000a    1. CTR+F -> Type -> Enter (Generic)\u000a    2. OCR "Search" -> Click -> Type -> Enter\u000a    3. Heuristic Top-Right Click -> Type -> Enter\u000a    4. Browser Ctrl+L -> Type -> Enter\u000a    """\u000a    print(f"🔍 Searching for ''{query}'' in {app_name} (Hybrid Mode)...", file=sys.stderr)\u000a    \u000a    # 0. Focus App\u000a    config = load_config()\u000a    profile = config.get(app_name.lower(), {})\u000a    win_title = resolve_window_title(app_name, config)\u000a    \u000a    wid = focus_window(win_title)\u000a    if not wid:\u000a        if no_launch:\u000a            print(f"❌ ''{app_name}'' not running and --no-launch check failed.", file=sys.stderr)\u000a            return False\u000a        # Launch\u000a        if not launch_app_safe(app_name):\u000a            return False\u000a        wid = focus_window(win_title)\u000a        if not wid:\u000a            print("❌ Failed to launch/focus app.", file=sys.stderr)\u000a            return False\u000a\u000a    time.sleep(1.0) # Wait for focus\u000a    subprocess.run([''xdotool'', ''windowraise'', wid], check=False)\u000a\u000a    # Layer 1: Generic Ctrl+F (Most Apps)\u000a    # But wait, browsers use Ctrl+L for address bar, or Ctrl+F for find in page.\u000a    # We want GLOBAL search usually?\u000a    # Context matters. For "Search for text", Ctrl+F is fine.\u000a    # For "Search web", Ctrl+L is better.\u000a    # Let''s try to detect context or just try Ctrl+F first?\u000a    # Actually OCR is cleaner.\u000a    \u000a    # Layer 2: OCR "Search"\u000a    print("👉 Layer 2: OCR Search Button", file=sys.stderr)\u000a    # Look for "Search", "Find", "Start"\u000a    for kw in ["Search", "Find", "Query"]:\u000a        fx, fy = capture_and_find_text(wid, kw)\u000a        if fx:\u000a            print(f"✅ OCR found ''{kw}'' at ({fx}, {fy}).")\u000a            pyautogui.click(fx, fy)\u000a            time.sleep(0.5)\u000a            # Clear text if needed?\u000a            pyautogui.hotkey(''ctrl'', ''a'')\u000a            pyautogui.write(query, interval=0.05)\u000a            pyautogui.press(''enter'')\u000a            print("✅ Search submitted via OCR.")\u000a            return True\u000a\u000a    # Layer 3: Heuristic (Top-Right / Search Icon Area)\u000a    # Most apps have search in top-right or top-center\u000a    print("👉 Layer 3: Heuristic Search (Top-Right)", file=sys.stderr)\u000a    try:\u000a        wx, wy, w, h = get_window_geometry(wid)\u000a        \u000a        # Target: Top Right, with padding\u000a        # Often search icon is ~50px from right, ~30-50px from top\u000a        h_x = wx + w - 50\u000a        h_y = wy + 40 \u000a        \u000a        # Verify safety\u000a        if validate_click_coordinates(h_x, h_y, app_name):\u000a            print(f"⚠️ Attempting heuristic click at Top-Right ({h_x}, {h_y})...")\u000a            # Move slowly\u000a            subprocess.run(["xdotool", "mousemove", str(h_x), str(h_y)])\u000a            time.sleep(0.5)\u000a            pyautogui.click(h_x, h_y)\u000a            time.sleep(0.5)\u000a            # CLEAR BEFORE SEARCH\u000a            pyautogui.hotkey(''ctrl'', ''a'')\u000a            pyautogui.press(''backspace'')\u000a            time.sleep(0.1)\u000a            pyautogui.write(query, interval=0.05)\u000a            pyautogui.press(''enter'')\u000a            print("✅ Search submitted via Heuristic.")\u000a            # We can''t be sure, but we tried.\u000a            return True\u000a    except Exception as e:\u000a        print(f"⚠️ Layer 3 failed: {e}")\u000a\u000a    # Layer 4: Browser Specific (Ctrl+L)\u000a    # Only if it LOOKS like a browser or explicitly allowed\u000a    is_browser = app_name.lower() in ["chrome", "firefox", "chromium", "brave", "edge", "browser"]\u000a    if is_browser:\u000a        print("👉 Layer 4: Browser Fallback (Ctrl+L)", file=sys.stderr)\u000a        pyautogui.hotkey(''ctrl'', ''l'')\u000a        time.sleep(0.5)\u000a        # Ctrl+L usually selects all, but let''s be safe\u000a        pyautogui.press(''backspace'')\u000a        pyautogui.write(query)\u000a        pyautogui.press(''enter'')\u000a        print("✅ Search submitted via Browser Shortcut.")\u000a        return True\u000a\u000a    print("❌ All search strategies failed.")\u000a    return False \u000a\u000aif __name__ == "__main__":\u000a    parser = argparse.ArgumentParser()\u000a    parser.add_argument("--action", required=True, help="Action to perform")\u000a    parser.add_argument("--text", help="Text to type")\u000a    parser.add_argument("--app", default="neontune", help="Application name")\u000a    \u000a    parser.add_argument("--x", type=int, help="Click X")\u000a    parser.add_argument("--y", type=int, help="Click Y")\u000a    parser.add_argument("--key", help="Key to press (e.g. enter, tab)")\u000a    parser.add_argument("--no-launch", action="store_true", help="Do not launch if app not found")\u000a    parser.add_argument("--clear", action="store_true", help="Clear field before typing (Ctrl+A, Backspace)")\u000a    parser.add_argument("--submit", action="store_true", help="Press Enter after typing")\u000a    \u000a    # Optional coordinate overrides (legacy support or manual override)\u000a    parser.add_argument("--sx", type=int, help="Search X")\u000a    parser.add_argument("--sy", type=int, help="Search Y")\u000a    parser.add_argument("--rx", type=int, help="Result X")\u000a    parser.add_argument("--ry", type=int, help="Result Y")\u000a    parser.add_argument("--debug-draw", action="store_true", help="Draw debug box around detected target")\u000a    \u000a    args = parser.parse_args()\u000a    \u000a    if args.debug_draw:\u000a        DEBUG_DRAW = True\u000a    \u000a    if args.action == "play_song":\u000a        # ... (Same as before) ...\u000a        # Can''t easily copy-paste 300 lines. \u000a        # I should use Sed or partial replace?\u000a        pass # Placeholder\u000a\u000a\u000a\u000a\u000adef get_ui_tree_json(app_name):\u000a    # get_atspi_tree now returns a DICT\u000a    elements = get_atspi_tree(app_name)\u000a    return json.dumps(elements)\u000a\u000adef get_ui_tree_hash(app_name):\u000a    """Returns a simple hash of the current UI tree structure to detect changes"""\u000a    result = get_atspi_tree(app_name)\u000a    if "error" in result:\u000a        return "error"\u000a    \u000a    # Check visual hash first if available\u000a    if "visual_hash" in result:\u000a        return result["visual_hash"]\u000a\u000a    elements = result.get("elements", [])\u000a    # Create a string representation of element names and roles\u000a    signature = "|".join([f"{e[''role'']}:{e[''text'']}" for e in elements])\u000a    import hashlib\u000a    return hashlib.md5(signature.encode()).hexdigest() if hasattr(hashlib, ''md5'') else str(hash(signature))\u000a\u000adef wait_for_tree_settle(app_name, timeout=10, stabilization_time=2):\u000a    """Wait until the UI tree structure stops changing"""\u000a    print(f"⏳ Waiting for UI in {app_name} to settle...", file=sys.stderr)\u000a    start_time = time.time()\u000a    last_hash = ""\u000a    stable_since = time.time()\u000a    \u000a    while time.time() - start_time < timeout:\u000a        current_hash = get_ui_tree_hash(app_name)\u000a        if current_hash != last_hash:\u000a            last_hash = current_hash\u000a            stable_since = time.time()\u000a        elif time.time() - stable_since >= stabilization_time:\u000a            print("✅ UI settled.", file=sys.stderr)\u000a            return True\u000a        time.sleep(0.5)\u000a    \u000a    print("⚠️ UI did not settle within timeout.", file=sys.stderr)\u000a    return False\u000a\u000adef play_song(app_name, song_query):\u000a    # 1. Config / Defaults\u000a    # We still use apps.json for launch command, but ignore coords if we can find text\u000a    config = load_config()\u000a    profile = config.get(app_name.lower(), {})\u000a    launch_cmd = profile.get("launch_cmd") or [app_name.lower()]\u000a    launch_cmd = profile.get("launch_cmd") or [app_name.lower()]\u000a    win_title = resolve_window_title(app_name, config) # Default to app_name instead of ''tao''\u000a    \u000a    # 2. Launch\u000a    wid = focus_window(win_title)\u000a    if not wid:\u000a        print(f"🚀 Launching {launch_cmd}...")\u000a        subprocess.Popen(launch_cmd)\u000a        time.sleep(5)\u000a        wid = focus_window(win_title)\u000a        if not wid:\u000a            print("❌ Failed to find window after launch.")\u000a            return\u000a\u000a    # 3. Find ''Search''\u000a    print("👀 Looking for ''Search'' button...")\u000a    sx, sy = capture_and_find_text(wid, "Search")\u000a    \u000a    if sx:\u000a        print(f"🖱️ Clicking ''Search'' at ({sx}, {sy})...", file=sys.stderr)\u000a        pyautogui.click(sx, sy)\u000a    else:\u000a        print("❌ ''Search'' not found. Aborting to prevent hallucination.", file=sys.stderr)\u000a        return\u000a\u000a    # 4. Type\u000a    print(f"⌨️ Typing ''{song_query}''...", file=sys.stderr)\u000a    time.sleep(1) # Wait for animation\u000a    # Clear just in case\u000a    pyautogui.hotkey(''ctrl'', ''a'')\u000a    pyautogui.press(''backspace'')\u000a    \u000a    pyautogui.write(song_query, interval=0.1)\u000a    pyautogui.press(''enter'')\u000a    \u000a    print("⏳ Waiting for results (3s)...", file=sys.stderr)\u000a    time.sleep(3)\u000a    \u000a    # 5. Find Result (Artist or Title)\u000a    # Search is case insensitive fuzzy\u000a    # Split query into potential keywords\u000a    parts = song_query.replace(''-'', '' '').split()\u000a    # Filter short words (avoid matching ''a'', ''the'', ''in'')\u000a    keywords = [w for w in parts if len(w) > 2]\u000a    \u000a    found_x, found_y = None, None\u000a    \u000a    # Try keywords \u000a    for word in keywords:\u000a        print(f"👀 Looking for result keyword ''{word}''...", file=sys.stderr)\u000a        fx, fy = capture_and_find_text(wid, word)\u000a        if fx:\u000a            found_x, found_y = fx, fy\u000a            break # Found a match\u000a    \u000a    if found_x:\u000a        print(f"🖱️ Clicking Result matching ''{word}'' at ({found_x}, {found_y})...")\u000a        pyautogui.click(found_x, found_y)\u000a        pyautogui.press(''enter'')\u000a        print("✅ Playing!")\u000a    else:\u000a        print("❌ No keywords found in OCR. Aborting to prevent hallucination.")\u000a        return\u000a\u000a\u000adef click_text(app_name, text):\u000a    """Focus app, find text via AT-SPI (Data) then OCR (Visual), and click it."""\u000a    print(f"🖱️ Request to click text ''{text}'' in {app_name}...", file=sys.stderr)\u000a    \u000a    # 1. Config/Focus\u000a    config = load_config()\u000a    profile = config.get(app_name.lower(), {})\u000a    win_title = resolve_window_title(app_name, config)\u000a    \u000a    wid = focus_window(win_title)\u000a    if not wid:\u000a        print(f"❌ Could not focus {app_name} to click text.", file=sys.stderr)\u000a        return False\u000a        \u000a    time.sleep(1.0) # Wait for focus and render\u000a    subprocess.run([''xdotool'', ''windowraise'', wid], check=False)\u000a\u000a    # 2. Strategy A: Data-First (AT-SPI)\u000a    # 100% Precision for accessible apps (Chrome, Firefox, LibreOffice, Gedit, etc.)\u000a    print(f"🧠 Data-Scan: Searching Accessibility Tree for ''{text}''...", file=sys.stderr)\u000a    \u000a    # We use get_atspi_tree to fetch the structured view of the app\u000a    # This includes "lazy poking" to ensure the tree is fresh\u000a    tree_data = get_atspi_tree(app_name)\u000a    \u000a    if "elements" in tree_data:\u000a        # Fuzzy match strategies\u000a        candidates = []\u000a        target_lower = text.lower()\u000a        \u000a        for el in tree_data["elements"]:\u000a            el_text = (el.get("text") or "").lower()\u000a            el_role = el.get("role", "")\u000a            \u000a            # 1. Exact Match\u000a            if el_text == target_lower:\u000a                print(f"✅ Data-Hit (Exact): Found ''{el[''text'']}'' ({el_role}) at ({el[''x'']}, {el[''y'']})")\u000a                pyautogui.click(el[''x''], el[''y''])\u000a                return True\u000a                \u000a            # 2. Contains Match\u000a            if target_lower in el_text:\u000a                candidates.append(el)\u000a\u000a        # If no exact match, check candidates\u000a        if candidates:\u000a            # Sort by length (shortest match is likely the label itself, not a huge paragraph containing it)\u000a            candidates.sort(key=lambda x: len(x.get("text", "")))\u000a            best = candidates[0]\u000a            print(f"✅ Data-Hit (Fuzzy): Found ''{best[''text'']}'' ({best[''role'']}) at ({best[''x'']}, {best[''y'']})")\u000a            pyautogui.click(best[''x''], best[''y''])\u000a            return True\u000a            \u000a    print("⚠️ Data-Scan: Text not found in Accessibility Tree. Falling back to Vision (OCR)...", file=sys.stderr)\u000a\u000a    # 3. Strategy B: Vision-Fallback (OCR)\u000a    # Used for Canvas apps, Games, or non-accessible widgets\u000a    print(f"👀 Vision-Scan: OCR Scanning for ''{text}''...", file=sys.stderr)\u000a    matches = find_text_matches(wid, text)\u000a    \u000a    if not matches:\u000a        print(f"⚠️ Text ''{text}'' not found in {app_name} (Data nor Vision).", file=sys.stderr)\u000a        return False\u000a\u000a    # Logic: Prefer matches NOT in the top header/search-bar area\u000a    # Assume header is top 80px of window (Reduced from 120px to avoid false positives)\u000a    win_x, win_y, _, _ = get_window_geometry(wid)\u000a    header_threshold = win_y + 80\u000a    \u000a    # Filter candidates below header\u000a    better_candidates = [m for m in matches if m[1] > header_threshold]\u000a    \u000a    if better_candidates:\u000a        if len(matches) > len(better_candidates):\u000a            print(f"ℹ️ Smart Click: Ignoring {len(matches) - len(better_candidates)} matches in header/search-bar.")\u000a        target = better_candidates[0]\u000a    else:\u000a        # Fallback to first match if that''s all we have\u000a        print("⚠️ Only found matches in header/top area. Clicking anyway.")\u000a        target = matches[0]\u000a\u000a    fx, fy, word = target\u000a    print(f"✅ Vision-Hit: Selected ''{word}'' at ({fx}, {fy}). Clicking...", file=sys.stderr)\u000a    pyautogui.click(fx, fy)\u000a    return True\u000a\u000adef validate_click_coordinates(x, y, app_name):\u000a    """\u000a    Validates if (x,y) is safe to click for the given app.\u000a    Checks:\u000a    1. Is it inside the window?\u000a    2. Is it in the header/corner safety zone (to avoid closing app)?\u000a    """\u000a    if not app_name: return True # Cannot validate without app context\u000a    \u000a    config = load_config()\u000a    profile = config.get(app_name.lower(), {})\u000a    win_title = resolve_window_title(app_name, config)\u000a    \u000a    wid = get_window_id(win_title)\u000a    if not wid:\u000a        print(f"⚠️ Cannot validate coordinates: Window ''{win_title}'' not found.", file=sys.stderr)\u000a        return True # Fail open if window not found? Or fail closed? \u000a                    # For safety, maybe fail open but warn.\u000a    \u000a    wx, wy, width, height = get_window_geometry(wid)\u000a    \u000a    if width == 0 or height == 0:\u000a        print("⚠️ Could not get window geometry for validation.", file=sys.stderr)\u000a        return True\u000a\u000a    # 1. Bounds Check\u000a    if not (wx <= x <= wx + width and wy <= y <= wy + height):\u000a        print(f"❌ Safety Violation: Click ({x},{y}) is outside window bounds ({wx},{wy} {width}x{height}).", file=sys.stderr)\u000a        return False\u000a\u000a    # 2. Safety Zone (Top Right Corner - Window Controls)\u000a    # Assume controls are in top 40px, rightmost 120px\u000a    # Relative to window\u000a    rel_x = x - wx\u000a    rel_y = y - wy\u000a    \u000a    if rel_y < 40 and rel_x > (width - 120):\u000a        print(f"❌ Safety Violation: Click ({x},{y}) is in Window Controls Safety Zone (Top-Right).", file=sys.stderr)\u000a        return False\u000a        \u000a    # 3. Header Warning (Drag Zone)\u000a    if rel_y < 30:\u000a        print(f"⚠️ Warning: Click ({x},{y}) is in Title Bar/Header area.", file=sys.stderr)\u000a        \u000a    return True\u000a\u000aLAUNCH_ALIASES = {\u000a    "chrome": ["google-chrome", "google-chrome-stable", "chromium", "chromium-browser", "chrome"],\u000a    "firefox": ["firefox"],\u000a    "spotify": ["spotify"],\u000a    "neontune": ["neontune"],\u000a    "calculator": ["gnome-calculator", "kcalc", "gcalctool", "calculator"],\u000a    "browser": ["google-chrome", "firefox", "chromium"],\u000a    "editor": ["gedit", "kate", "mousepad", "code"]\u000a}\u000a\u000a# Built-in window title fragments for well-known apps — used for dynamic focus without apps.json\u000aWINDOW_TITLE_ALIASES = {\u000a    "chrome": "Google Chrome",\u000a    "google chrome": "Google Chrome",\u000a    "google-chrome": "Google Chrome",\u000a    "chromium": "Chromium",\u000a    "firefox": "Mozilla Firefox",\u000a    "spotify": "Spotify",\u000a    "vscode": "Visual Studio Code",\u000a    "code": "Visual Studio Code",\u000a    "vs code": "Visual Studio Code",\u000a    "terminal": "Terminal",\u000a    "neontune": "tao",\u000a    "tao": "tao",\u000a    "slack": "Slack",\u000a    "discord": "Discord",\u000a    "files": "Files",\u000a    "nautilus": "Files",\u000a    "gedit": "gedit",\u000a    "calculator": "Calculator",\u000a    "vlc": "VLC",\u000a}\u000a\u000adef resolve_window_title(app_name: str, config: dict = None) -> str:\u000a    """\u000a    Resolve the best window title string for a given app name.\u000a    Priority:\u000a    1. apps.json config (user-defined)\u000a    2. Built-in WINDOW_TITLE_ALIASES\u000a    3. Fuzzy xdotool search (finds any window with app name in title/class)\u000a    4. Raw app_name as fallback\u000a    """\u000a    key = app_name.lower().strip()\u000a    \u000a    # 1. User config\u000a    if config:\u000a        profile = config.get(key, {})\u000a        wt = profile.get("window_title")\u000a        if wt:\u000a            return wt\u000a    \u000a    # 2. Built-in aliases\u000a    if key in WINDOW_TITLE_ALIASES:\u000a        return WINDOW_TITLE_ALIASES[key]\u000a    \u000a    # 3. Fuzzy xdotool: search for any window with app_name in title\u000a    try:\u000a        out = subprocess.check_output(\u000a            ["xdotool", "search", "--name", app_name],\u000a            stderr=subprocess.DEVNULL\u000a        ).decode().strip()\u000a        wids = [w for w in out.split(''\\n'') if w]\u000a        if wids:\u000a            # Get the title of the largest matching window\u000a            best_title = None\u000a            max_area = 0\u000a            for wid in wids:\u000a                try:\u000a                    _, _, w, h = get_window_geometry(wid)\u000a                    if w * h > max_area and w > 100 and h > 100:\u000a                        max_area = w * h\u000a                        title_out = subprocess.check_output(\u000a                            ["xdotool", "getwindowname", wid],\u000a                            stderr=subprocess.DEVNULL\u000a                        ).decode().strip()\u000a                        best_title = title_out\u000a                except Exception:\u000a                    continue\u000a            if best_title:\u000a                print(f"🔍 Dynamic window found for ''{app_name}'': ''{best_title}''", file=sys.stderr)\u000a                return best_title\u000a    except Exception:\u000a        pass\u000a    \u000a    # 4. Fallback: return raw name\u000a    return app_name\u000a\u000adef launch_app_safe(app_name, explicit_cmd=None):\u000a    """Try to launch an app using config cmd or known aliases."""\u000a    config = load_config()\u000a    win_title = resolve_window_title(app_name, config)\u000a    \u000a    # Add aliases for command\u000a    cmds = []\u000a    if explicit_cmd:\u000a        cmds.append(explicit_cmd)\u000a    \u000a    aliases = LAUNCH_ALIASES.get(app_name.lower(), [app_name.lower()])\u000a    if isinstance(aliases, list):\u000a        cmds.extend(aliases)\u000a    else:\u000a        cmds.append(aliases)\u000a        \u000a    # SAFETY: Check if app has a window already before launching!\u000a    if focus_window(win_title):\u000a        print(f"✅ App ''{app_name}'' is already running with a window. Skipping launch.", file=sys.stderr)\u000a        return True\u000a\u000a    for cmd in cmds:\u000a        if isinstance(cmd, list): cmd_str = cmd[0]\u000a        else: cmd_str = cmd\u000a            \u000a        print(f"🚀 Trying launch command: {cmd_str}...")\u000a        try:\u000a            # Detach process so it survives agent exit\u000a            subprocess.Popen(\u000a                cmd if isinstance(cmd, list) else [cmd],\u000a                start_new_session=True, \u000a                stdout=subprocess.DEVNULL, \u000a                stderr=subprocess.DEVNULL\u000a            )\u000a            \u000a            # Verification Step: Wait for window\u000a            print(f"⏳ Verification: Waiting for ''{app_name}'' window to appear...", file=sys.stderr)\u000a            for _ in range(10): # 10 seconds timeout\u000a                if focus_window(win_title):\u000a                    print(f"✅ Verified: ''{app_name}'' launched and focused.", file=sys.stderr)\u000a                    return True\u000a                time.sleep(1)\u000a            print(f"❌ Failed to launch ''{app_name}''. Process started but window not found.", file=sys.stderr)\u000a            return False\u000a        except FileNotFoundError:\u000a            continue\u000a        except Exception as e:\u000a            print(f"⚠️ Launch error for {cmd_str}: {e}")\u000a            continue\u000a            \u000a    # Fallback: Try the app name directly if it wasn''t already tried\u000a    if app_name.lower() not in [str(c).lower() for c in cmds]:\u000a        print(f"🚀 Trying generic launch: {app_name}...")\u000a        try:\u000a            subprocess.Popen(\u000a                [app_name],\u000a                start_new_session=True,\u000a                stdout=subprocess.DEVNULL,\u000a                stderr=subprocess.DEVNULL\u000a            )\u000a            # Verification Step: Wait for window\u000a            print(f"⏳ Verification: Waiting for ''{app_name}'' window to appear...", file=sys.stderr)\u000a            for _ in range(10): # 10 seconds timeout\u000a                if focus_window(win_title):\u000a                    print(f"✅ Verified: ''{app_name}'' launched and focused.", file=sys.stderr)\u000a                    return True\u000a                time.sleep(1)\u000a            print(f"❌ Failed to launch ''{app_name}''. Process started but window not found.", file=sys.stderr)\u000a            return False\u000a        except:\u000a            pass\u000a\u000a    print(f"❌ Failed to launch ''{app_name}''. No matching executable found.")\u000a    return False\u000a\u000adef search_in_app(app_name, query, no_launch=False):\u000a    """\u000a    Hybrid Search Strategy:\u000a    1. Atspi (Accessibility Tree) - Find ''Search''/''Find'' inputs.\u000a    2. OCR (Visual) - Find text ''Search'', ''Type to search''.\u000a    3. Heuristic - Click Top-Right (Search Icon area).\u000a    4. Browser Fallback - Ctrl+L.\u000a    """\u000a    print(f"🔍 Searching for ''{query}'' in {app_name} (Hybrid Mode)...")\u000a    \u000a    config = load_config()\u000a    profile = config.get(app_name.lower(), {})\u000a    win_title = resolve_window_title(app_name, config)\u000a    \u000a    # 1. Ensure App is Running & Focused\u000a    if not focus_window(win_title):\u000a        if no_launch:\u000a            print(f"⚠️ App {app_name} not found and no_launch=True.")\u000a            return False\u000a        if not launch_app_safe(app_name):\u000a            return False\u000a            \u000a    wid = focus_window(win_title) # Refresh WID\u000a    if not wid: return False\u000a    \u000a    # Layer 1: Atspi (Accessibility)\u000a    print("👉 Layer 1: Accessibility Search", file=sys.stderr)\u000a    try:\u000a        tree_data = get_atspi_tree(app_name)\u000a        # Handle dict return (new format) or list (legacy)\u000a        elements = tree_data.get("elements", []) if isinstance(tree_data, dict) else tree_data\u000a        \u000a        if isinstance(elements, list):\u000a            search_terms = ["search", "find", "jump to", "filter", "category", "categories", "type to", "address", "url", "omnibox"]\u000a            target_el = None\u000a            \u000a            for e in elements:\u000a                name = (e.get("text") or "").lower()\u000a                role = (e.get("role") or "").lower()\u000a                \u000a                # Priority: Entry/Text with search-like name\u000a                if role in ["entry", "text", "push button", "glossary", "icon", "label", "autocomplete"]:\u000a                    if any(t in name for t in search_terms):\u000a                        target_el = e\u000a                        break\u000a                        \u000a            if target_el:\u000a                print(f"✅ Atspi found target: ''{target_el[''text'']}'' ({target_el[''role'']}) at ({target_el[''x'']},{target_el[''y'']})")\u000a                pyautogui.click(target_el[''x''], target_el[''y''])\u000a                time.sleep(0.5)\u000a                # Select all just in case\u000a                if role == "entry": pyautogui.hotkey(''ctrl'', ''a'')\u000a                pyautogui.write(query, interval=0.05)\u000a                pyautogui.press(''enter'')\u000a                print("✅ Search submitted via Atspi.")\u000a                return True\u000a    except Exception as e:\u000a        print(f"⚠️ Layer 1 failed: {e}", file=sys.stderr)\u000a\u000a    # Layer 2: OCR (Visual)\u000a    print("👉 Layer 2: Visual Search (OCR)", file=sys.stderr)\u000a    keywords = ["Search", "Type to search", "Find", "Jump to", "Quick actions"]\u000a    for kw in keywords:\u000a        # Use find_text_matches to get all candidates\u000a        matches = find_text_matches(wid, kw)\u000a        if matches:\u000a            # Prefer matches NOT in header (Smart Search Logic)\u000a            win_x_geo, win_y_geo, _, _ = get_window_geometry(wid)\u000a            header_thresh = win_y_geo + 80 # Reduced from 120 to 80 to be less aggressive\u000a            \u000a            valid_matches = [m for m in matches if m[1] > header_thresh]\u000a            target = valid_matches[0] if valid_matches else matches[0]\u000a            \u000a            fx, fy, _ = target\u000a            print(f"✅ OCR found ''{kw}'' at ({fx}, {fy}).")\u000a            pyautogui.click(fx, fy)\u000a            time.sleep(0.5)\u000a            # Clear text if needed?\u000a            pyautogui.hotkey(''ctrl'', ''a'')\u000a            pyautogui.write(query, interval=0.05)\u000a            pyautogui.press(''enter'')\u000a            print("✅ Search submitted via OCR.")\u000a            return True\u000a\u000a    # Layer 3: Browser Specific (Ctrl+L) - FALLBACK\u000a    # Only use if we couldn''t find an on-page search bar\u000a    is_browser = app_name.lower() in ["chrome", "google-chrome", "firefox", "chromium", "brave", "edge", "browser"]\u000a    if is_browser:\u000a        print("👉 Layer 3: Browser Shortcut (Ctrl+L)", file=sys.stderr)\u000a        pyautogui.hotkey(''ctrl'', ''l'')\u000a        time.sleep(0.5)\u000a        pyautogui.write(query, interval=0.05)\u000a        pyautogui.press(''enter'')\u000a        print("✅ Search submitted via Browser Shortcut.")\u000a        return True\u000a        pyautogui.write(query)\u000a        pyautogui.press(''enter'')\u000a        print("✅ Search submitted via Browser Shortcut.")\u000a        return True\u000a\u000a    print("❌ All search strategies failed.")\u000a    return False\u000a\u000aif __name__ == "__main__":\u000a    parser = argparse.ArgumentParser()\u000a    parser.add_argument("--action", required=True, help="Action to perform")\u000a    parser.add_argument("--text", help="Text to type")\u000a    parser.add_argument("--app", default="neontune", help="Application name")\u000a    \u000a    parser.add_argument("--x", type=int, help="Click X")\u000a    parser.add_argument("--y", type=int, help="Click Y")\u000a    parser.add_argument("--key", help="Key to press (e.g. enter, tab)")\u000a    parser.add_argument("--no-launch", action="store_true", help="Do not launch if app not found")\u000a    parser.add_argument("--clear", action="store_true", default=True, help="Clear field before typing (Default: True)")\u000a    parser.add_argument("--no-clear", action="store_false", dest="clear", help="Do not clear field before typing")\u000a    parser.add_argument("--submit", action="store_true", help="Press Enter after typing")\u000a    \u000a    # Optional coordinate overrides (legacy support or manual override)\u000a    parser.add_argument("--sx", type=int, help="Search X")\u000a    parser.add_argument("--sy", type=int, help="Search Y")\u000a    parser.add_argument("--rx", type=int, help="Result X")\u000a    parser.add_argument("--ry", type=int, help="Result Y")\u000a    parser.add_argument("--debug-draw", action="store_true", help="Draw debug box around detected target")\u000a    \u000a    args = parser.parse_args()\u000a    \u000a    if args.debug_draw:\u000a        DEBUG_DRAW = True\u000a    \u000a    if args.action == "play_song":\u000a        if not args.text:\u000a            print("❌ --text required for play_song", file=sys.stderr)\u000a            sys.exit(1)\u000a        play_song(args.app, args.text)\u000a        \u000a    elif args.action == "search":\u000a        if not args.text:\u000a            print("❌ --text required for search", file=sys.stderr)\u000a            sys.exit(1)\u000a        if not search_in_app(args.app, args.text, no_launch=args.no_launch):\u000a            sys.exit(1)\u000a\u000a    elif args.action == "get_screen_text":\u000a        print(get_screen_text(args.app, args.text))\u000a\u000a    elif args.action == "click":\u000a        if args.x is not None and args.y is not None:\u000a            if args.app:\u000a                config = load_config()\u000a                profile = config.get(args.app.lower(), {})\u000a                win_title = resolve_window_title(args.app, config)\u000a                wid = focus_window(win_title)\u000a                if wid:\u000a                    subprocess.run([''xdotool'', ''windowraise'', wid], check=False)\u000a                    time.sleep(0.5)\u000a                else:\u000a                    # STRICT FOCUS CHECK\u000a                    print(f"❌ Focus Failed: Could not find window matching ''{win_title}'' for app ''{args.app}''. Aborting click.", file=sys.stderr)\u000a                    sys.exit(1)\u000a\u000a            print(f"🖱️ Clicking at ({args.x}, {args.y})...", file=sys.stderr)\u000a            \u000a            # SAFETY CHECK\u000a            if not validate_click_coordinates(args.x, args.y, args.app):\u000a                print("⛔ Click aborted due to safety checks.", file=sys.stderr)\u000a                sys.exit(1)\u000a\u000a            # Move first to visualize\u000a            subprocess.run(["xdotool", "mousemove", str(args.x), str(args.y)], check=False)\u000a            time.sleep(0.2)\u000a            pyautogui.click(args.x, args.y)\u000a            print("✅ Click executed.", file=sys.stderr)\u000a        elif args.text and args.app:\u000a            click_text(args.app, args.text)\u000a        else:\u000a            print(f"❌ --text (with --app) OR --x and --y required for click", file=sys.stderr)\u000a            \u000a    elif args.action == "launch":\u000a        # Generic launch\u000a        if not launch_app_safe(args.app):\u000a            sys.exit(1)\u000a\u000a    elif args.action == "scroll":\u000a        # direction: ''up'' or ''down'' (text arg)\u000a        # amount: pixels (y arg)\u000a        direction = args.text or "down"\u000a        amount = args.y or 300\u000a        if direction == "down":\u000a            print(f"📜 Scrolling DOWN {amount} pixels...", file=sys.stderr)\u000a            pyautogui.scroll(-amount)\u000a        else:\u000a            print(f"📜 Scrolling UP {amount} pixels...", file=sys.stderr)\u000a            pyautogui.scroll(amount)\u000a    \u000a    elif args.action == "type":\u000a        # Improved type: focus first if app provided\u000a        if args.app:\u000a            config = load_config()\u000a            profile = config.get(args.app.lower(), {})\u000a            win_title = resolve_window_title(args.app, config)\u000a            # STRICT FOCUS CHECK: Do not type if we can''t find the window!\u000a            if not focus_window(win_title):\u000a                print(f"❌ Focus Failed: Could not find window matching ''{win_title}'' for app ''{args.app}''. Aborting type.", file=sys.stderr)\u000a                sys.exit(1)\u000a            \u000a        if args.text:\u000a            target_text = args.text\u000a            print(f"⌨️ Targeting text: {target_text}", file=sys.stderr)\u000a            \u000a            # ATTEMPT TO DETECT EXISTING TEXT\u000a            already_typed = False\u000a            try:\u000a                # Get the focused element''s name/value via atspi\u000a                desktop = Atspi.get_desktop(0)\u000a                focused = desktop.get_focused_element()\u000a                if focused:\u000a                    val = focused.get_name() or ""\u000a                    if target_text.lower() in val.lower() or val.lower() in target_text.lower():\u000a                        print(f"✅ Field already contains ''{val}''. Skipping redundant typing.", file=sys.stderr)\u000a                        already_typed = True\u000a            except:\u000a                pass\u000a\u000a            if not already_typed:\u000a                if args.clear:\u000a                    print("⌨️ Clearing field...", file=sys.stderr)\u000a                    pyautogui.hotkey(''ctrl'', ''a'')\u000a                    pyautogui.press(''backspace'')\u000a                    time.sleep(0.2)\u000a\u000a                pyautogui.write(target_text, interval=0.05)\u000a            \u000a        if args.key or args.submit:\u000a            key_to_press = args.key or "enter"\u000a            print(f"⌨️ Pressing key: {key_to_press}", file=sys.stderr)\u000a            pyautogui.press(key_to_press)\u000a\u000a    elif args.action == "focus":\u000a        if args.app:\u000a            config = load_config()\u000a            profile = config.get(args.app.lower(), {})\u000a            win_title = resolve_window_title(args.app, config)\u000a            focus_window(win_title)\u000a        else:\u000a            print("❌ --app required for focus", file=sys.stderr)\u000a            \u000a    elif args.action == "wait":\u000a        seconds = args.y or 5\u000a        print(f"⏳ Waiting for {seconds} seconds...", file=sys.stderr)\u000a        time.sleep(seconds)\u000a    \u000a    elif args.action == "close_active":\u000a        # Dismiss the currently focused window/popup (via Alt+F4 or Escape)\u000a        method = (args.text or "escape").lower()\u000a        if method == "alt+f4":\u000a            print("🔴 Closing active window via Alt+F4...", file=sys.stderr)\u000a            pyautogui.hotkey(''alt'', ''F4'')\u000a        else:\u000a            print("⎋ Dismissing active popup via Escape...", file=sys.stderr)\u000a            pyautogui.press(''escape'')\u000a        time.sleep(0.3)\u000a        \u000a    elif args.action == "check_app" or args.action == "InstallApp":\u000a        # Simplified check: is it in PATH?\u000a        app = args.app.lower()\u000a        aliases = LAUNCH_ALIASES.get(app, [app])\u000a        found = False\u000a        for a in aliases:\u000a            if subprocess.run(["which", a], capture_output=True).returncode == 0:\u000a                print(f"✅ Found {app} as {a}", file=sys.stderr)\u000a                found = True\u000a                break\u000a        if not found:\u000a            print(f"❌ {app} not found on system.", file=sys.stderr)\u000a\u000a    elif args.action == "status":\u000a        app = args.app\u000a        config = load_config()\u000a        profile = config.get(app.lower(), {})\u000a        win_title = resolve_window_title(app, config)\u000a        if focus_window(win_title):\u000a            print(f"✅ {app} is RUNNING.", file=sys.stderr)\u000a        else:\u000a            print(f"❌ {app} is NOT RUNNING.", file=sys.stderr)\u000a\u000a    elif args.action == "get_ui_tree":\u000a        # Returns dict {"elements": [], "visual_hash": "..."}\u000a        result = get_atspi_tree(args.app)\u000a        print(json.dumps(result))\u000a\u000a    elif args.action == "wait_for_text":\u000a        if args.app and args.text:\u000a            wait_for_text(args.app, args.text, timeout=args.y or 20)\u000a        else:\u000a            print("❌ --app and --text required for wait_for_text", file=sys.stderr)\u000a\u000a    elif args.action == "analyze_repo":\u000a        repo_url = args.text\u000a        if not repo_url:\u000a            print("❌ --text/repo_url required for analyze_repo", file=sys.stderr)\u000a            sys.exit(1)\u000a        print(f"📦 Analyzing repository: {repo_url}...", file=sys.stderr)\u000a        dest = "/tmp/repo"\u000a        subprocess.run(["rm", "-rf", dest])\u000a        res = subprocess.run(["git", "clone", "--depth", "1", repo_url, dest], capture_output=True)\u000a        if res.returncode == 0:\u000a            print(f"✅ Repository cloned to {dest}")\u000a        else:\u000a            print(f"❌ Failed to clone repository: {res.stderr.decode()}")\u000a            sys.exit(1)\u000a\u000a    else:\u000a        print(f"❌ Unknown action: {args.action}", file=sys.stderr)\u000a        sys.exit(1)\u000a'),'python','1.0.0',NULL,'2026-03-14 06:42:50','2026-03-14 06:42:50','agents-scripts/desktop/ui_automation.py',NULL);
INSERT INTO tools VALUES(7438474706707156992,'get_mouse_position','get_mouse_position tool for desktop domain',unistr('#!/usr/bin/env python3\u000aimport pyautogui\u000aimport time\u000aimport sys\u000a\u000aprint("Move your mouse over the UI elements you want to identify.")\u000aprint("Refreshes every 0.5 seconds. Press Ctrl+C to stop.")\u000aprint("-" * 50)\u000a\u000atry:\u000a    while True:\u000a        x, y = pyautogui.position()\u000a        position_str = ''X: '' + str(x).rjust(4) + '' Y: '' + str(y).rjust(4)\u000a        print(position_str, end='''')\u000a        print(''\\b'' * len(position_str), end='''', flush=True)\u000a        time.sleep(0.5)\u000aexcept KeyboardInterrupt:\u000a    print(''\\nDone.'')\u000a'),'python','1.0.0',NULL,'2026-03-14 06:42:50','2026-03-14 06:42:50','agents-scripts/desktop/get_mouse_position.py',NULL);
INSERT INTO tools VALUES(7438474706707156993,'ocr_dump','ocr_dump tool for desktop domain',unistr('import sys\u000aimport re\u000aimport xml.etree.ElementTree as ET\u000a\u000adef dump_layout(file_path):\u000a    try:\u000a        tree = ET.parse(file_path)\u000a        root = tree.getroot()\u000a        for elem in root.iter():\u000a            if ''ocrx_word'' in (elem.get(''class'') or ""):\u000a                text = elem.text or ""\u000a                if text.strip():\u000a                    title = elem.get(''title'')\u000a                    match = re.search(r''bbox (\\d+) (\\d+) (\\d+) (\\d+)'', title)\u000a                    if match:\u000a                        x1, y1, x2, y2 = map(int, match.groups())\u000a                        print(f"''{text}'' : {x1},{y1} {x2},{y2}")\u000a    except Exception as e:\u000a        print(f"Error: {e}")\u000a\u000aif __name__ == "__main__":\u000a    dump_layout("hocr_dump.hocr")\u000a'),'python','1.0.0',NULL,'2026-03-14 06:42:50','2026-03-14 06:42:50','agents-scripts/desktop/ocr_dump.py',NULL);
