INSERT INTO tools VALUES(9223372036854775807,'vision_analysis','Analyze images and perform OCR. Native implementation.','// Native Implementation','rust','1.0.0',NULL,'2026-03-15 06:02:43','2026-03-15 06:02:43',NULL,NULL);
INSERT INTO tools VALUES(7438900000000000004,'http_request','Perform HTTP GET/POST requests',unistr('#!/usr/bin/env python3\u000aimport sys\u000aimport json\u000aimport requests\u000a\u000adef main():\u000a    if len(sys.argv) < 2:\u000a        print(json.dumps({"error": "No URL provided"}))\u000a        sys.exit(1)\u000a\u000a    url = sys.argv[1]\u000a    method = "GET"\u000a    body = None\u000a    \u000a    # Try to parse complex input if it''s JSON\u000a    try:\u000a        input_data = json.loads(url)\u000a        url = input_data.get("url", url)\u000a        method = input_data.get("method", "GET").upper()\u000a        body = input_data.get("body")\u000a    except:\u000a        pass\u000a\u000a    try:\u000a        if method == "POST":\u000a            resp = requests.post(url, data=body, timeout=30)\u000a        else:\u000a            resp = requests.get(url, timeout=30)\u000a            \u000a        print(resp.text)\u000a    except Exception as e:\u000a        print(json.dumps({"error": str(e)}))\u000a\u000aif __name__ == "__main__":\u000a    main()\u000a'),'python','1.0.0',NULL,'2026-03-15 16:02:02','2026-03-15 16:02:02','http_request.py',NULL);
INSERT INTO tools VALUES(7770000000000000002,'app_launcher','Lightweight application launcher',unistr('#!/usr/bin/env python3\u000aimport subprocess\u000aimport sys\u000aimport os\u000aimport time\u000aimport re\u000a\u000adef get_window_id(app_name):\u000a    """Finds window ID by class name or title."""\u000a    try:\u000a        # Get all windows with class (-x)\u000a        output = subprocess.check_output([''wmctrl'', ''-lx'']).decode()\u000a        for line in output.splitlines():\u000a            # Match class (e.g., neontune.Neontune)\u000a            if app_name.lower() in line.lower():\u000a                match = re.search(r''0x[0-9a-f]+'', line)\u000a                if match:\u000a                    return match.group(0)\u000a    except:\u000a        pass\u000a    return None\u000a\u000adef is_running(app_name):\u000a    """Checks if a process with app_name is already running."""\u000a    try:\u000a        subprocess.check_call([''pgrep'', ''-i'', ''-x'', app_name.lower()], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)\u000a        return True\u000a    except subprocess.CalledProcessError:\u000a        return False\u000a\u000adef focus_window(app_name):\u000a    """Attempts to bring the application window to the front by ID."""\u000a    print(f"🎯 Locating {app_name} window...")\u000a    wid = get_window_id(app_name)\u000a    if wid:\u000a        print(f"✅ Found window {wid}. Focusing...")\u000a        subprocess.run([''wmctrl'', ''-i'', ''-a'', wid], check=False)\u000a        return True\u000a    \u000a    # Fallback to name-based if ID fails\u000a    print(f"⚠️ Window ID not found, trying name-based focus...")\u000a    subprocess.run([''wmctrl'', ''-x'', ''-a'', app_name], check=False)\u000a    subprocess.run([''wmctrl'', ''-a'', app_name], check=False)\u000a    return False\u000a\u000adef main():\u000a    raw_args = sys.argv[1:]\u000a    if len(raw_args) == 1 and " " in raw_args[0]:\u000a        raw_args = raw_args[0].split()\u000a    \u000a    if not raw_args:\u000a        print("❌ No application specified")\u000a        sys.exit(1)\u000a        \u000a    app_name = raw_args[1] if raw_args[0] == "launch" and len(raw_args) > 1 else raw_args[0]\u000a    \u000a    if is_running(app_name):\u000a        print(f"✅ {app_name} is already running.")\u000a        focus_window(app_name)\u000a        print("⌛ Settling...")\u000a        time.sleep(2)\u000a        sys.exit(0)\u000a\u000a    print(f"🚀 Launching {app_name}...")\u000a    try:\u000a        launched = False\u000a        try:\u000a            path = subprocess.check_output([''which'', app_name.lower()]).decode().strip()\u000a            if path:\u000a                subprocess.Popen([path], start_new_session=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)\u000a                launched = True\u000a        except: pass\u000a            \u000a        if not launched:\u000a            subprocess.Popen([app_name.lower()], start_new_session=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)\u000a            launched = True\u000a\u000a        if launched:\u000a            print(f"✅ Launch command sent. Settling for 5s...")\u000a            time.sleep(5)\u000a            focus_window(app_name)\u000a            sys.exit(0)\u000a            \u000a    except Exception as e:\u000a        print(f"❌ Failed to launch {app_name}: {e}")\u000a        sys.exit(1)\u000a\u000aif __name__ == "__main__":\u000a    main()\u000a'),'python','1.0.0',NULL,'2026-03-16 13:16:08','2026-03-16 13:16:08','app_launcher',NULL);
INSERT INTO tools VALUES(1742000000000000,'charting','Generate data visualizations. Use ONLY when explicitly asked for a "chart" or "graph", or for comparing 3 or more data points. NEVER use for simple facts, versions, or 2-item comparisons. Input must be a JSON object with fields: chart_type (bar/line/pie), title (string), labels (array of strings), data (array of floats). Example: {"chart_type": "line", "title": "Growth", "labels": ["2024", "2025", "2026"], "data": [1.6, 2.5, 3.0]}','// Native Implementation','rust','1.0.0',NULL,'2026-03-19 07:13:28','2026-03-19 07:13:28',NULL,'chart,graph,plot,visualize,visualization,draw,sketch,diagram,pie,bar,mapped');
